  ui_story_5038_50380001_37_dialog_content = "อย่างที่คุณเห็น เมื่อเร็ว ๆ นี้ Umbwaton ได้ว่าจ้าง Courier Union เพื่อช่วยขนของจำนวนมาก <color=#FFB400>กระดาษสีแดง</color>.",
  ui_story_5038_50380001_38_dialog_content = "เนื่องจากเป็นออร์เดอร์จำนวนมากและเร่งด่วนมาก ฉันจึงทำงานล่วงเวลาเพื่อจัดส่งให้หมด...",
