  ui_story_5038_50380001_85_dialog_content = "ราวกับว่าทวีปที่อยู่อีกด้านหนึ่งเป็นโลกที่แตกต่างไปจากเดิมอย่างสิ้นเชิง",
  ui_story_5038_50380001_86_dialog_content = "และและฉันพนันได้เลยว่าพวกเขามีวันหยุดที่แตกต่างกันโดยสิ้นเชิงด้วย!",
  ui_story_5038_50380001_87_dialog_content = "เอกสารสีแดงทั้งหมดที่ฉันส่งไปในวันนี้ต้องเป็นของเทศกาล twaditional",
