  ui_story_5038_50380001_92_dialog_content = "ฉันสามารถบอกได้เพียงแค่ดูที่เสื้อผ้าของคุณ",
  ui_story_5038_50380001_93_dialog_content = "จังหวะเหมาะครับท่าน! นี่คือกระดาษสีแดงที่ร้านค้าของคุณสั่งซื้อ โปรดลงชื่อที่นี่!",
