  ui_story_5038_50380001_95_dialog_content = "ขอโทษที่ถาม แต่ฉันสงสัยว่าทำไมคุณถึงสั่งกระดาษสีแดงจำนวนมากจาก Umbraton?",
  ui_story_5038_50380001_96_dialog_content = "มีความสำคัญต่อการต้อนรับปีใหม่",
  ui_story_5038_50380001_97_dialog_content = "เป็นประเพณีใน Longzhou ที่จะแขวนกระดาษสีแดงสองแผ่นที่มีคำว่า \"Blessing\" ไว้ที่ประตูสำหรับเทศกาลฤดูใบไม้ผลิ",
  ui_story_5038_50380001_98_dialog_content = "พวกเขาช่วยให้เราอธิษฐานขอให้โชคดีและความเจริญรุ่งเรืองในปีหน้า",
  ui_story_5038_50380001_99_dialog_content = "หลงโจว—นั่นคือชื่อของทวีปตะวันออกใช่หรือไม่?",
  ui_story_5038_50380001_100_dialog_content = "จับได้เห็นชัดตรงเผง. ดูเหมือนพวกคุณจะไม่ค่อยคุ้นเคยกับพวกเรามากนัก",
  ui_story_5038_50380001_101_dialog_content = "พวกเราที่อาศัยอยู่ที่นี่ใน Twin Pavilions Bay ค่อนข้างจะเลี้ยงตัวเองได้ และไม่ค่อยมีปฏิสัมพันธ์กับสถานที่ที่อยู่ไกลออกไป",
  ui_story_5038_50380001_102_dialog_content = "เราสามารถมีและจะซื้อกระดาษสีแดงนี้ได้อย่างง่ายดายในร้านค้าในพื้นที่ของเราเอง",
  ui_story_5038_50380001_103_dialog_content = "แต่ปีนี้...มีเหตุนิดหน่อย",
  ui_story_5038_50380001_104_dialog_content = "สถานการณ์แบบไหน?",
  ui_story_5038_50380001_105_dialog_content = "ร้านเราล้างสต๊อกหมดแล้ว ไม่ใช่แค่กระดาษแต่เป็นทุกอย่างรวมถึงของใช้จำเป็นด้วย",
