  ui_story_5038_50380001_107_dialog_content = "โดยปกติแล้วกิลด์ของลิน <color=#FFB400>เรือจัดหา</color> มาทุกๆสองสามเดือนจากหลงโจว",
  ui_story_5038_50380001_108_dialog_content = "แต่เราไม่เห็นร่องรอยของมันในช่วงครึ่งปีที่ผ่านมา เราไม่รู้ว่าเกิดอะไรขึ้น",
  ui_story_5038_50380001_109_dialog_content = "ร้านค้าที่พึ่งพาเรือเสบียงในการซื้อสินค้าคงคลังไม่สามารถคงอยู่ได้ตลอดไป",
  ui_story_5038_50380001_110_dialog_content = "กระดาษสีแดงเป็นส่วนหนึ่งของสิ่งที่ขาดหายไป ดังนั้นเราจึงไม่มีทางเลือกอื่นนอกจากสั่งจาก Umbraton",
  ui_story_5038_50380001_111_dialog_content = "(อา เป็นสิ่งที่เกิดขึ้น ฟังดูน่ากังวล...)",
  ui_story_5038_50380001_112_dialog_content = "(กิลด์หลินเคยช่วยฉันมาก่อน แต่ฉันไม่รู้ว่าพวกเขาเป็นยังไงบ้าง)",
  ui_story_5038_50380001_113_dialog_content = "อ๋อ...รู้ความรู้สึก คุณต้องคิดถึงรสชาติของที่บ้านอย่างแน่นอน",
  ui_story_5038_50380001_114_dialog_content = "<color=#e8d9bb>ฮึ่ม...ฮึ่ม...</color>",
  ui_story_5038_50380001_115_dialog_content = "มันคือที่ไหนน่ะ?",
  ui_story_5038_50380001_116_dialog_content = "เสียงแตรดังมาจากท่าเรือ...",
  ui_story_5038_50380001_117_dialog_content = "นั่นคือ... หมอกของเรือ!",
  ui_story_5038_50380001_118_dialog_content = "แน่นอน! ฉันจะรู้จักหมอกได้ทุกที่!",
  ui_story_5038_50380001_119_dialog_content = "มีเรืออยู่ที่ท่าเรือ! อาจจะเป็น Lin Guild?",
  ui_story_5038_50380001_120_dialog_content = "เรือเสบียงของ Lin Guild เหรอ?",
  ui_story_5038_50380001_121_dialog_content = "ดูเหมือนว่าเรามาถูกเวลาพอดี",
  ui_story_5038_50380001_122_dialog_content = "มันคือเรือเสบียงจริงๆ!",
  ui_story_5038_50380001_123_dialog_content = "โอ้ ขอบคุณพระเจ้า! ฉันกังวลว่าจะไม่ได้อะไรเลยสำหรับเทศกาลฤดูใบไม้ผลิ!",
  ui_story_5038_50380001_124_dialog_content = "มีคนกำลังมา!",
  ui_story_5038_50380001_125_dialog_content = "...",
  ui_story_5038_50380001_126_dialog_content = "(มีชายแปลกหน้าอยู่ตรงนั้น ดูไม่ตื่นเต้นแม้แต่น้อย)",
  ui_story_5038_50380001_127_dialog_content = "ออกจากทาง! ให้เขาผ่าน! หาพื้นที่ให้คนชรา อ่อนแอ ป่วย พิการ!",
  ui_story_5038_50380001_128_dialog_content = "คุณชายหนุ่ม! คุณกำลังปิดกั้นล้อ!",
  ui_story_5038_50380001_129_dialog_content = "ต-นั่นที่เขานั่งอยู่คือ...รถเข็นเหรอ?!",
  ui_story_5038_50380001_130_dialog_content = "ฉันขอโทษ! มารยาทของฉันอยู่ที่ไหน",
  ui_story_5038_50380001_131_dialog_content = "ไม่รบกวน ฉันพูดไปหลายครั้งแล้ว ลี่ชิง เจ้าหนู อย่าเหมารวมว่า...",
  ui_story_5038_50380001_132_dialog_content = "ฉันยังไม่ตาย สมองยังทำงานได้ดี",
  ui_story_5038_50380001_133_dialog_content = "ฮ่า ๆ ๆ ๆ! ฉันแค่อยากจะพาเราผ่านฝูงชนเร็วขึ้น!",
  ui_story_5038_50380001_134_dialog_content = "ฉันรอคอยที่จะซื้อสมุนไพรที่น่าทึ่งของหลงโจวมาโดยตลอด!",
  ui_story_5038_50380001_135_dialog_content = "ขอผ่าน! ฉันก่อน! ฉันนำไนเทียมมา!",
  ui_story_5038_50380001_136_dialog_content = "ขยับขึ้น! ต่อไป!",
  ui_story_5038_50380001_137_dialog_content = "ฮะ? อย่าผลัก!",
  ui_story_5038_50380001_138_dialog_content = "เงียบกันทุกคน",
  ui_story_5038_50380001_139_dialog_content = "...",
  ui_story_5038_50380001_140_dialog_content = "Shadowind ได้รับการปรับปรุงใหม่จริงๆ แม้แต่กัปตันยังเป็นหน้าใหม่",
  ui_story_5038_50380001_141_dialog_content = "ฉันชื่อ Yuebai กัปตันคนใหม่ของเรือการค้าของ Lin Guild Shadowind",
  ui_story_5038_50380001_142_dialog_content = "... ดูเหมือนว่าพวกคุณจะจำสมาชิก Lin ที่เดินทางกับเรือลำนี้ได้",
  ui_story_5038_50380001_143_dialog_content = "ครึ่งปีที่ผ่านมาเห็นการเปลี่ยนแปลงเชิงกลยุทธ์บางอย่างในตระกูล Lin ซึ่งส่งผลให้พวกเขาไม่สามารถส่งเรือออกทะเลได้",
  ui_story_5038_50380001_144_dialog_content = "ฉันแน่ใจว่าการตัดเส้นทางระหว่าง Longzhou และ Astra เป็นเวลานานเป็นเรื่องยาก",
  ui_story_5038_50380001_145_dialog_content = "แต่นั่นก็เป็นอดีตไปแล้ว ตอนนี้ Shadowind มีฉันเป็นผู้ควบคุม",
  ui_story_5038_50380001_146_dialog_content = "เส้นทาง Longzhou-Astra จะเป็นทางการ <color=#FFB400>ดำเนินธุรกิจต่อ</color>.",
  ui_story_5038_50380001_147_dialog_content = "... พวกเขาทำได้จริงๆ จงซู! พวกเขามาจริงๆ!",
  ui_story_5038_50380001_148_dialog_content = "เรากลับไปได้แล้ว!",
  ui_story_5038_50380001_149_dialog_content = "...",
  ui_story_5038_50380001_150_dialog_content = "เรากลับไปที่หลงโจวได้ไหม? เป็นแบบนั้น? แต่ยังไม่ได้เตรียม...",
  ui_story_5038_50380001_151_dialog_content = "ใช่ ฉันมีกำหนดการประชุมกับคู่ค้าทางธุรกิจของฉันแล้ว ฉันสงสัยว่าฉันจะออกจากพวกเขา ...",
  ui_story_5038_50380001_152_dialog_content = "ใครก็ตามที่ต้องการกลับไปที่หลงโจวต้องซื้อตั๋วเท่านั้น",
  ui_story_5038_50380001_153_dialog_content = "อย่างไรก็ตาม เนื่องจากเส้นทางขากลับมีการเปลี่ยนแปลง โปรดระวังสิ่งที่เกี่ยวข้อง <color=#FFB400>ความเสี่ยง</color>.",
  ui_story_5038_50380001_154_dialog_content = "ไม่เป็นไร! เรือ Lin ใด ๆ ก็เชื่อถือได้! ขอตั๋วสามใบให้ฉันด้วย!",
  ui_story_5038_50380001_155_dialog_content = "ให้ฉันก่อน! ไม่อยากทะเลาะกับพวกมัน...",
  ui_story_5038_50380001_156_dialog_content = "ขอให้ทุกคนใจเย็นๆ ไม่จำเป็นต้องตื่นตระหนก",
  ui_story_5038_50380001_157_dialog_content = "ยังเหลือเวลาอีกพอสมควรก่อนเดินทางกลับ",
  ui_story_5038_50380001_158_dialog_content = "ฉันบอกได้เลยว่าทุกคนที่นี่เป็นคนดีตั้งแต่วินาทีที่ฉันลงจากเรือ",
  ui_story_5038_50380001_159_dialog_content = "สุภาพบุรุษหรือสตรีคนใดอาจปรารถนาให้ตัวตนอันต่ำต้อยของฉันอ่านดวงชะตาของพวกเขาได้ อาจช่วยให้เส้นทางของพวกเขาสว่างขึ้นได้บ้าง?",
  ui_story_5038_50380001_160_dialog_content = "และ Tianxian นักต้มตุ๋นก็โจมตีอีกครั้ง หลอกล่อผู้คนด้วยลิ้นสีเงินของเขา...",
  ui_story_5038_50380001_161_dialog_content = "ทำไมเจ้าหญิง Dantang! ไม่มีใครโกหก ฉันรับรองกับคุณ",
  ui_story_5038_50380001_162_dialog_content = "... ระวังนะเจ้าหญิง!",
  ui_story_5038_50380001_163_dialog_content = "Ooooooo!",
  ui_story_5038_50380001_164_dialog_content = "ว้าว! Shadowind ดูดีขึ้นกว่าเดิม!",
  ui_story_5038_50380001_165_dialog_content = "กว้างขวางขึ้นมากอีกด้วย...",
  ui_story_5038_50380001_166_dialog_content = "ฮิฮิฮิ... การตอบสนองที่รวดเร็วอย่างน่าประทับใจ Jiu",
  ui_story_5038_50380001_167_dialog_content = "<color=#e8d9bb>*ฝูงชนพึมพำ*</color>",
  ui_story_5038_50380001_168_dialog_content = "เฮ้อ...",
  ui_story_5038_50380001_169_dialog_content = "คุณสบายดีไหม ทวีตตี้?",
  ui_story_5038_50380001_170_dialog_content = "ฉันอยากไปดู Shadowind เหมือนกัน...",
  ui_story_5038_50380001_171_dialog_content = "ฉันพนันได้เลยว่ามีสิ่งที่น่าสนใจมากมายให้ดู",
  ui_story_5038_50380001_172_dialog_content = "คุณหมายถึงแบบนี้ คนส่งของน้อย?",
  ui_story_5038_50380001_173_dialog_content = "ว้าว!! กองกระดาษวัวแดง!",
  ui_story_5038_50380001_174_dialog_content = "นั่นคือแสง! นั่นคือสิ่งที่ฉันกำลังมองหา!",
  ui_story_5038_50380001_175_dialog_content = "ฉันได้ยินมาว่า Twin Pavilions Bay กำลังหมดเสบียงตั้งแต่ก่อนที่เราจะออกไปด้วยซ้ำ เทศกาลฤดูใบไม้ผลิใกล้จะมาถึงแล้ว ไม่น้อยไปกว่ากัน",
  ui_story_5038_50380001_176_dialog_content = "พวกเขาไม่มีทางเลือกอื่นนอกจากจัดหาเสบียงจากกิลด์ในประเทศแล้วจัดการคนส่งของจำนวนมากเพื่อส่งทุกอย่าง",
  ui_story_5038_50380001_177_dialog_content = "อย่างไรก็ตาม ตอนนี้กระดาษจาก Longzhou มาถึงแล้ว สิ่งต่างๆ จะไม่ยุ่งยากสำหรับคุณ",
  ui_story_5038_50380001_178_dialog_content = "<size=50>เย้! ฉันฟินแล้ว!!</size>",
  ui_story_5038_50380001_179_dialog_content = "ในที่สุดทวีตตี้ก็หมดเวลา",
  ui_story_5038_50380001_180_dialog_content = "คุณสามคนมาจาก Astra ในประเทศหรือไม่?",
  ui_story_5038_50380001_181_dialog_content = "แค่ดูเสื้อผ้าเราก็รู้แล้วใช่ไหมคะ?",
  ui_story_5038_50380001_182_dialog_content = "ฉันหวังว่าจะได้รับการต้อนรับของคุณแล้ว",
  ui_story_5038_50380001_183_dialog_content = "Shadowind จะยังคงอยู่ในน่านน้ำของ Astra ชั่วขณะหนึ่ง",
  ui_story_5038_50380001_184_dialog_content = "ให้เราได้รู้จักกันในช่วงเวลานี้",
  ui_story_5038_50380001_185_dialog_content = "(ว้าว! ช่างเป็นผู้หญิงที่อดทนและสง่างาม!)",
  ui_story_5038_50380001_186_dialog_content = "S-แน่นอน ฉัน PlayerName.",
  ui_story_5038_50380001_187_dialog_content = "ยินดีต้อนรับสู่ Astra แขกจากหลงโจว!",
  ui_story_5038_50380101_1_dialog_content = "<color=#e8d9bb>Twin Pavilions Bay Streets</color>",
  ui_story_5038_50380101_2_dialog_content = "(เวลาของเราอยู่ที่นี่เหมือนวันหยุดยาวที่หาได้ยาก...)",
  ui_story_5038_50380101_3_dialog_content = "(Twin Pavilions Bay เป็นสถานที่พักผ่อนในช่วงเทศกาลฤดูใบไม้ผลิ)",
  ui_story_5038_50380101_4_dialog_content = "คิดอะไรอยู่ PlayerName?",
  ui_story_5038_50380101_5_dialog_content = "ฉันแค่คิดว่าเวลาผ่านไปเร็วแค่ไหน ฉันไม่รู้ด้วยซ้ำว่าเราอยู่ที่นี่มานานแค่ไหนแล้ว",
  ui_story_5038_50380101_6_dialog_content = "ฉันทำ. ฉันเก็บไดอารี่ที่มีรายละเอียดมาก",
  ui_story_5038_50380101_7_dialog_content = "ให้ฉันดู... PlayerName และ Tianxian ใช้เวลาสามวันแรกในการเดินเตร็ดเตร่ใน Eastern Specialty Snack Street...",
  ui_story_5038_50380101_8_dialog_content = "วันที่สี่ถึงหกหมดไปกับการที่เรามีส่วนร่วมในเกมหมากรุก Twin Pavilions Bay...",
  ui_story_5038_50380101_9_dialog_content = "วันที่เจ็ดถึงสิบ แพ้อย่างน่าสังเวชในการแข่งขันคัดลายมือเทศกาลฤดูใบไม้ผลิของ Dantang...",
  ui_story_5038_50380101_10_dialog_content = "วันที่สิบถึงสิบห้า—",
  ui_story_5038_50380101_11_dialog_content = "โอเค โอเค... ได้เลย!",
  ui_story_5038_50380101_12_dialog_content = "ยังไงซะเราก็น่าจะเริ่มวางแผนออกเดินทางกันเร็วๆ นี้",
  ui_story_5038_50380101_13_dialog_content = "ใช้เวลานานเท่าที่คุณต้องการ PlayerName... แต่พรุ่งนี้ฉันต้องไปอิลลูมิน่า",
  ui_story_5038_50380101_14_dialog_content = "อะไร เร็ว ๆ นี้?!",
  ui_story_5038_50380101_15_dialog_content = "ถึงเวลาแล้วที่ห่วงโซ่อุปทานฤดูหนาวพิเศษของอิลลูมินาจะเริ่มทำงาน",
  ui_story_5038_50380101_16_dialog_content = "ต้องไปช่วยแจก",
  ui_story_5038_50380101_17_dialog_content = "และฉันต้องไปนอร์ธแลนด์ตามประเพณี เพื่อใช้เวลาช่วงปีใหม่กับราชินีเบธเลเฮม",
  ui_story_5038_50380101_18_dialog_content = "ถ้าไม่มีอะไรล่าช้า โค้ชของฉันจากนอร์ธแลนด์น่าจะมาถึงที่นี่ในคืนนี้",
  ui_story_5038_50380101_19_dialog_content = "คุณก็เช่นกัน คาร์ลีน?",
  ui_story_5038_50380101_20_dialog_content = "ดีจังวันหยุดยาว มันสนุก ...",
  ui_story_5038_50380101_21_dialog_content = "วะ!! ดูสิว่าฉันพบใคร!",
  ui_story_5038_50380101_22_dialog_content = "สวัสดีตอนเช้า คุณเนวิเกเตอร์ คุณรอง คุณคาร์วีน!",
  ui_story_5038_50380101_23_dialog_content = "มอร์นิ่ง ทวิตตี้!",
  ui_story_5038_50380101_24_dialog_content = "ทำงานเป็นไงบ้าง? ยังยุ่งอยู่?",
  ui_story_5038_50380101_25_dialog_content = "สบายดี! กลับสู่ภาวะปกติแล้ว!",
  ui_story_5038_50380101_26_dialog_content = "มีเพียงสิ่งเดียวที่จะทำลายทิ้ง!",
  ui_story_5038_50380101_27_dialog_content = "คุณยังต้องการความช่วยเหลือหรือไม่? ฉันยังมีเวลาก่อนที่จะต้องออกเดินทาง",
  ui_story_5038_50380101_28_dialog_content = "ขอบคุณ Miss Vice แต่ฉันมีสิ่งนี้! และคาดเดาอะไร",
  ui_story_5038_50380101_29_dialog_content = "ฉันซื้อ <color=#FFB400>ตั๋ว</color> สำหรับ Shadowind!",
  ui_story_5038_50380101_30_dialog_content = "คุณจะเชื่อหรือไม่? นี่คือจดหมายทางไกล! มันจะต้องถูกส่งไปยังหลงโจว!",
  ui_story_5038_50380101_31_dialog_content = "ฉันระมัดระวังอย่างมากที่จะทำลายคนอื่นๆ ทั้งหมดแต่เนิ่นๆ ดังนั้นฉันจึงไม่พลาดเรือ!",
  ui_story_5038_50380101_32_dialog_content = "ดูเหมือนจะเป็นโอกาสที่ดีที่จะเดินทาง",
  ui_story_5038_50380101_33_dialog_content = "ฮิฮิ! ฉันรอคอยที่จะทำมัน!",
  ui_story_5038_50380101_34_dialog_content = "ดูเหมือนว่าทุกคนสามารถพูดคุยเกี่ยวกับการจากไปของ Shadowind ที่ใกล้เข้ามา",
  ui_story_5038_50380101_35_dialog_content = "ใช่ บางคนกังวลเล็กน้อย",
  ui_story_5038_50380101_36_dialog_content = "คุณรู้ไหมว่า... ฉันมี <color=#FFB400>ตักด้านใน</color> ว่าทำไมตระกูลลินต้องระงับเส้นทางเป็นเวลาหกเดือน!",
  ui_story_5038_50380101_37_dialog_content = "เอ่อ... คุณเป็นใคร?",
  ui_story_5038_50380101_38_dialog_content = "โอ้ฉันจำได้! คุณเป็นคนดีที่ช่วยคนแก่บนรถเข็น!",
  ui_story_5038_50380101_39_dialog_content = "ฮ่าๆ! ฉันไม่ใช่แค่ผู้ชายที่ดี! Zhong Xu เป็นเพื่อนของฉันเช่นเดียวกับคนไข้ของฉัน",
  ui_story_5038_50380101_40_dialog_content = "เราเป็นผู้โดยสารด้วยกันบนเรือลำเดียวกันเมื่อเรามาจากหลงโจว",
  ui_story_5038_50380101_41_dialog_content = "ฉันชื่อลี่ชิง ฉันเป็นหมอแมวพเนจร ไปไหนมาไหนและช่วยชีวิต!",
  ui_story_5038_50380101_42_dialog_content = "เมี้ยว!",
  ui_story_5038_50380101_43_dialog_content = "เหวอ!",
  ui_story_5038_50380101_44_dialog_content = "ต-ถ-นั่นมันแมว!",
  ui_story_5038_50380101_45_dialog_content = "เอาล่ะ Tinytail ทำตัว! ฉันขอโทษ เขาแค่พูดเล่น",
  ui_story_5038_50380101_46_dialog_content = "มานี่สิ Tinytail",
  ui_story_5038_50380101_47_dialog_content = "เห็นได้ชัดว่าเขาชอบบริษัทของฉันมากกว่าบริษัทของคุณ",
  ui_story_5038_50380101_48_dialog_content = "เพียงเพราะแมวตัวอื่นที่อยู่รอบตัวคุณ...",
  ui_story_5038_50380101_49_dialog_content = "ขอโทษ ฉันมาที่นี่เพื่อยืนยันรายละเอียดผู้โดยสาร",
  ui_story_5038_50380101_50_dialog_content = "คนปัจจุบัน—นั่นคือทวีตี้ จงซู และลี่ชิง—ยืนยันการจองของพวกเขากลับไปยังหลงโจวได้หรือไม่?",
  ui_story_5038_50380101_51_dialog_content = "ใช่!",
  ui_story_5038_50380101_52_dialog_content = "ดีมาก. ก่อนที่เราจะออกเดินทาง ฉันมีประกาศอีกเล็กน้อย",
  ui_story_5038_50380101_53_dialog_content = "ชาวหลงโจว ฉันแน่ใจว่าคุณเคยได้ยินเกี่ยวกับเข็มทิศมหาสมุทรในตำนานของตระกูลหลิน",
  ui_story_5038_50380101_54_dialog_content = "พวกเขาเคยพึ่งพาวัตถุนี้เพื่อรักษาอำนาจสูงสุดในการเดินเรือ",
  ui_story_5038_50380101_55_dialog_content = "น่าเสียดายที่สมบัติพิเศษนี้สูญหายไปและป่านนี้ยังไม่ได้กู้คืน",
  ui_story_5038_50380101_56_dialog_content = "ฉันได้กล่าวถึงเรื่องนี้แล้ว แต่โปรดแน่ใจว่าคุณเข้าใจถึงความเสี่ยงของการเดินทางที่กำลังจะมาถึงของเรา",
  ui_story_5038_50380101_57_dialog_content = "เราไม่มีประสบการณ์ในการเดินเรือโดยไม่มีเข็มทิศ ดังนั้น นี่จะเป็นการผจญภัยทางทะเล",
  ui_story_5038_50380101_58_dialog_content = "ระหว่างทางเรามีสภาพที่เอื้ออำนวย ซึ่งทำให้การเดินทางปลอดภัยและปราศจากเหตุการณ์ใดๆ",
  ui_story_5038_50380101_59_dialog_content = "อย่างไรก็ตาม ฉันไม่สามารถรับประกันได้ว่าการเดินทางกลับจะเหมือนเดิม ฉันต้องแน่ใจว่าผู้โดยสารทุกคนรับทราบเรื่องนี้เป็นอย่างดี",
  ui_story_5038_50380101_60_dialog_content = "โดยส่วนตัวแล้วฉันจะ <color=#FFB400>ไม่แนะนำ</color> ขึ้น Shadowind โดยไม่มีเหตุผลที่ดี",
  ui_story_5038_50380101_61_dialog_content = "(นี่เป็นหนึ่งในเหตุการณ์ที่ Lins กำลังเผชิญกับครึ่งปีหลังนี้หรือเปล่า...?)",
  ui_story_5038_50380101_62_dialog_content = "ฉันไม่หวั่น! ฉันเชื่อมั่นใน Miss Yuebai!",
  ui_story_5038_50380101_63_dialog_content = "คุณเป็นคนกล้าหาญใช่ไหม",
  ui_story_5038_50380101_64_dialog_content = "อาจจะบังเอิญ แต่เนื่องจากฉันไปบอกทุกคนเกี่ยวกับเรื่องนี้...",
  ui_story_5038_50380101_65_dialog_content = "ทุกคนที่มีตั๋วถูกยกเลิกทันที",
  ui_story_5038_50380101_66_dialog_content = "บางคนบอกว่าต้องอยู่ต่อเพราะเหตุผลทางครอบครัว บ้างก็ว่าเปลี่ยนแผนกระทันหัน",
  ui_story_5038_50380101_67_dialog_content = "ฉันสงสัยว่าเป็นเพราะไม่มีใครเต็มใจที่จะเสี่ยงชีวิตจริง ๆ เมื่อมีการผลักดันเข้ามา",
  ui_story_5038_50380101_68_dialog_content = "แต่ในกรณีนั้น คุณก็กำลังขอชีวิตเช่นกัน มิสยูไป๋!",
  ui_story_5038_50380101_69_dialog_content = "... ฉันมีศรัทธาในความสามารถของฉันที่จะจัดการสิ่งต่างๆ และอย่างไรก็ตามนี่คืองานของฉัน",
  ui_story_5038_50380101_70_dialog_content = "คุณดูไม่มั่นใจในตัวเองเป็นพิเศษ",
  ui_story_5038_50380101_71_dialog_content = "คุณไม่อยากรู้เกี่ยวกับที่ไหน <color=#FFB400>เข็มทิศ</color> จบลงด้วยการ?",
  ui_story_5038_50380101_72_dialog_content = "?!?",
  ui_story_5038_50380101_73_dialog_content = "คุณเป็นหนึ่งใน Lins หรือไม่? หรือ...",
  ui_story_5038_50380101_74_dialog_content = "เจ๋งไปเลยกัปตันเรือ! เราอยู่ที่นั่นจริงๆในช่วง <color=#FFB400>เหตุการณ์</color> หกเดือนที่ผ่านมา",
  ui_story_5038_50380101_75_dialog_content = "เป็นไปไม่ได้... เท่าที่ฉันรู้ ไม่มีวิญญาณสักดวงเดียวที่สามารถหลบหนีจากเงื้อมมือของโจรสลัดได้...",
  ui_story_5038_50380101_76_dialog_content = "หากคุณไม่รู้ด้วยซ้ำ โจรสลัดจะไม่รู้อย่างแน่นอน!",
  ui_story_5038_50380101_77_dialog_content = "และอย่างไรก็ตาม ฉันค่อนข้างมั่นใจว่าไม่ใช่แค่ฉันและ Zhong Xu ชราที่นี่ที่ไม่ได้ตกลงไปในส่วนลึกของมหาสมุทรในตอนนั้น",
  ui_story_5038_50380101_78_dialog_content = "คุณคือคุณ Zhong Xu ฉันคิดว่า?",
  ui_story_5038_50380101_79_dialog_content = "ครับคุณผู้หญิง.",
  ui_story_5038_50380101_80_dialog_content = "Guildmaster เป็นห่วงความปลอดภัยของคุณมากที่สุด เขาจะยินดีที่ได้รู้ว่าคุณยังมีชีวิตอยู่",
  ui_story_5038_50380101_81_dialog_content = "ฮิฮิ ดังนั้นเขาจึงหนีไปได้ด้วยเหรอ?",
  ui_story_5038_50380101_82_dialog_content = "คุณเป็นกัปตันที่กล้าหาญอย่างน่าทึ่ง ฉันชื่นชมความดื้อรั้นของคุณในการกลับมาใช้เส้นทางอีกครั้ง",
  ui_story_5038_50380101_83_dialog_content = "ฉันคิดว่าคุณไม่ได้มาที่นี่เพื่อเดินทางส่งสินค้าเท่านั้น! แน่นอนว่าภารกิจของคุณคือการค้นหา The Compass ด้วย?",
  ui_story_5038_50380101_84_dialog_content = "... ใช่แล้ว",
  ui_story_5038_50380101_85_dialog_content = "หากคุณยังคงมุ่งมั่นที่จะขึ้นเรือ โปรดช่วยฉันด้วย",
  ui_story_5038_50380101_86_dialog_content = "แน่นอน! มาคุยกันให้มากขึ้นเมื่อเราอยู่บนเรือ เราไม่ควรปล่อยให้แขกในประเทศของเรายืนอยู่แถวนี้",
  ui_story_5038_50380101_87_dialog_content = "ย-คุณหมายถึงเรา? อย่าสนใจเราเลยจริงๆ...",
  ui_story_5038_50380101_88_dialog_content = "อย่างไรก็ตาม เราจะออกเดินทางในอีกสองวันนับจากนี้ ฉันเดาว่าฉันจะได้พบคุณที่ท่าเรือ",
  ui_story_5038_50380101_89_dialog_content = "<color=#e8d9bb>2 วันให้หลัง</color>",
  ui_story_5038_50380101_90_dialog_content = "โอ้ถ้าไม่ใช่ PlayerName!",
  ui_story_5038_50380101_91_dialog_content = "มาหาเราใช่ไหม",
  ui_story_5038_50380101_92_dialog_content = "อืม คาร์ลีนและไวซ์ได้จากไปแล้ว แต่อยากให้ฉันส่งข้อความถึงพวกคุณ",
  ui_story_5038_50380101_93_dialog_content = "\"เราขอให้คุณเดินทางอย่างราบรื่นและปลอดภัย และหวังว่าคุณจะกลับมาที่แอสตร้าอีกครั้งในเร็วๆ นี้\"",
  ui_story_5038_50380101_94_dialog_content = "นั่นคือสิ่งที่ฉันต้องการจะพูดเช่นกัน",
  ui_story_5038_50380101_95_dialog_content = "ฉันรู้ว่าเราเพิ่งพบกันได้ไม่นาน แต่ฉันก็ยังเสียใจเล็กน้อยที่เราต้องบอกลาเร็วเกินไป",
