  ui_story_5038_50380101_97_dialog_content = "เจ้าหญิงดันตัง เจ้าอยากจะลองพูดอะไรตอบกลับดูไหม?",
  ui_story_5038_50380101_98_dialog_content = "เอ่อ... M-Me? เอ่อ...",
  ui_story_5038_50380101_99_dialog_content = "ฉันจะจำคุณด้วยความรักเช่นกัน PlayerName.",
  ui_story_5038_50380101_100_dialog_content = "Zhong Xu และ Tianxian อยู่บนเรือแล้ว เราควรจะไปเหมือนกัน",
  ui_story_5038_50380101_101_dialog_content = "โอ้! นั่นทำให้ฉันนึกถึง... นกสีขาวตัวเล็ก ๆ จากวันก่อนอยู่ที่ไหน?",
  ui_story_5038_50380101_102_dialog_content = "... ถูกต้อง? ฉันอยากจะบอกลาทวีตตี้ด้วย",
  ui_story_5038_50380101_103_dialog_content = "<size=50>วะฮะฮะฮะฮะ—</size>",
  ui_story_5038_50380101_104_dialog_content = "<size=50>PlayerName! H-ช่วยฉันด้วย!</size>",
  ui_story_5038_50380101_105_dialog_content = "อา! มาแล้ว ทวีตตี้!",
  ui_story_5038_50380101_106_dialog_content = "ฉันไม่สามารถส่งโพสต์ทั้งหมดของฉันให้เสร็จได้!",
  ui_story_5038_50380101_107_dialog_content = "ทันใดนั้นฉันก็ได้รับการจัดส่งอย่างเร่งด่วนใน Northland! Couwier Union ไม่สามารถส่งใครได้อีก!",
  ui_story_5038_50380101_108_dialog_content = "มันคร่ำครวญในส่วนเหล่านั้น และทัศนวิสัยก็ต่ำมาก ฉันเป็นคนเดียวที่คุ้นเคยกับพื้นที่นี้มากพอ!",
  ui_story_5038_50380101_109_dialog_content = "ดังนั้น...คุณกำลังจะบอกว่าคุณ...",
  ui_story_5038_50380101_110_dialog_content = "ซู่... ฉันมาเพื่อถามว่าคุณจะช่วยฉันอีกไหม PlayerName?",
  ui_story_5038_50380101_111_dialog_content = "ฉันคิดว่าฉันจะจ้างคุณไปหว่องโจวให้ฉันได้!",
  ui_story_5038_50380101_112_dialog_content = "ฉันจ่ายได้! รอจนกว่าฉันจะได้รับเงินเดือนเดือนหน้า! ฉันจะให้คุณทั้งหมด!",
  ui_story_5038_50380101_113_dialog_content = "(ฟังดูคุ้นเคย...)",
  ui_story_5038_50380101_114_dialog_content = "ฉันต้องการช่วยคุณจริง ๆ และเงินไม่ใช่สิ่งสำคัญ!",
  ui_story_5038_50380101_115_dialog_content = "แต่ประเด็นคือ ตั๋วของคุณโอนได้ไหม?",
  ui_story_5038_50380101_116_dialog_content = "เป็นอะไรไปล่ะ",
  ui_story_5038_50380101_117_dialog_content = "นางเยว่ไป๋!!",
  ui_story_5038_50380101_118_dialog_content = "อ๋อ... อืมมม... ฉันเข้าใจแล้ว",
  ui_story_5038_50380101_119_dialog_content = "โดยปกติแล้ว ตั๋วจะไม่สามารถคืนเงินและโอนไม่ได้",
