  ui_story_5038_50380101_121_dialog_content = "ฉันจะไปขอให้ผู้โดยสารบนเรือช่วยแทน...",
  ui_story_5038_50380101_122_dialog_content = "อย่างไรก็ตาม ในฐานะกัปตัน ฉันยินดีที่จะเชิญคุณขึ้นเรือ PlayerName.",
  ui_story_5038_50380101_123_dialog_content = "ฮะ?! เป็นเรื่องที่ดี แต่จู่ๆ ก็เซอร์ไพรส์...",
