  ui_story_5038_50380101_129_dialog_content = "เรายังมี Zhong Xu และ Liqing ซึ่งทั้งคู่อยู่ที่นั่นตอนที่ The Compass หายไป",
  ui_story_5038_50380101_130_dialog_content = "เจ้าหญิง Dantang, Jiu และ Tianxian จะทำทุกอย่างที่ทำได้เพื่อให้เรือปลอดภัย",
