  ui_story_5038_50380101_144_dialog_content = "เหมาะสำหรับการแล่นเรือ",
  ui_story_5038_50380101_145_dialog_content = "มันจับใบเรือของ Shadowind แล้ว ดูเหมือนว่าจะมาจาก... ทิศตะวันตกเฉียงใต้",
  ui_story_5038_50380101_146_dialog_content = "ฉันจะเคลียร์เด็ค โปรดนั่งให้แน่นทุกคน!",
  ui_story_5038_50380101_147_dialog_content = "Shadowind ออกเดินทาง!",
  ui_story_5038_50380201_1_dialog_content = "(ช่างเป็นเรือที่น่าทึ่งจริงๆ มันใหญ่กว่าทุกลำที่ฉันเคยไปมา)",
  ui_story_5038_50380201_2_dialog_content = "(แม้แต่การออกแบบเด็คก็เต็มไปด้วยเอกลักษณ์ของตะวันออกไกล)",
  ui_story_5038_50380201_3_dialog_content = "(วิวสวยด้วย...)",
  ui_story_5038_50380201_4_dialog_content = "(อาห์! ท้องฟ้าสีคราม เกลียวคลื่น สายลมทะเล...)",
  ui_story_5038_50380201_5_dialog_content = "หา?",
  ui_story_5038_50380201_6_dialog_content = "Zhong Xu ทำไมคุณมาอยู่ที่นี่คนเดียว จ้องมองไปที่ทะเล หลงอยู่ในความคิด?",
