  ui_story_5038_50380201_10_dialog_content = "คุณต้องคิดถึงมันมาก",
  ui_story_5038_50380201_11_dialog_content = "โอ้นั่นทำให้ฉันนึกถึง ก่อนที่เราจะจากไป ฉันรู้สึกประทับใจว่าชาว Twin Pavilions Bay ระยะยาวจำนวนมากจะมากับเรา",
  ui_story_5038_50380201_12_dialog_content = "ฉันไม่เคยคิดเลยว่ามันจะจบลงด้วยการที่คุณและ Liqing อยู่บนเรือ",
  ui_story_5038_50380201_13_dialog_content = "เมื่อคุณท่องไปในต่างแดนนานเกินไป คุณมักจะอยากกลับบ้าน",
  ui_story_5038_50380201_14_dialog_content = "ผู้ที่คืนตั๋วของพวกเขายังคงคิดถึงบ้านเกิดของพวกเขา แต่เมล็ดพันธุ์แห่งความเป็นเจ้าของได้หยั่งรากลงใน Twin Pavilions Bay แล้ว",
  ui_story_5038_50380201_15_dialog_content = "พวกเขามีครอบครัวใน Twin Pavilions Bay และเพื่อนใหม่ การคิดถึงบ้านเกิดเป็นความคิดถึงที่เศร้าโศกมากกว่าสิ่งอื่นใด",
  ui_story_5038_50380201_16_dialog_content = "มีเพียงคนอย่างฉันเท่านั้นที่สามารถไปไหนมาไหนได้อย่างอิสระดั่งสายลมโดยไม่มีอะไรมาผูกมัดพวกเขา",
