  ui_story_5038_50380201_30_dialog_content = "พวกเขารวมกลุ่มกันในโรงเรียนและว่ายน้ำในทะเลลึกทันทีที่พวกเขาเกิด",
  ui_story_5038_50380201_31_dialog_content = "ไม่ว่าพวกเขาจะว่ายน้ำได้ไกลแค่ไหน พอถึงฤดูหนาว พวกเขาก็จะรวมเข้ากับโรงเรียนใกล้เคียงอื่นๆ อย่างสม่ำเสมอ",
  ui_story_5038_50380201_32_dialog_content = "จากนั้นพวกมันจะอพยพกลับไปที่ท่าเรือของหลงโจว ซึ่งพวกมันวางไข่ในบริเวณน้ำตื้น... และวงจรก็เริ่มต้นขึ้นอีกครั้ง",
