  ui_story_5038_50380202_19_dialog_content = "เพื่อปกป้องเข็มทิศและป้องกันไม่ให้ถูกทำลายหรือถูกขโมย Guildmaster Lin ตัดสินใจให้ญาติสนิทนำมันออกไป",
  ui_story_5038_50380202_20_dialog_content = "เข็มทิศถูกขนขึ้นเรือลำเก่า ซึ่งออกจากท่าเรือทันทีและมุ่งหน้าไปยังทะเลเปิด เราไปกับมัน",
  ui_story_5038_50380202_21_dialog_content = "พวกเขาแล่นเรือด้วยเข็มทิศ? ไม่เข้าใจ... ออกทะเลอันตรายกว่าแน่นอน?",
  ui_story_5038_50380202_22_dialog_content = "จะดีกว่าไหมที่จะขังมันไว้ในห้องนิรภัยหรืออะไรทำนองนั้น",
  ui_story_5038_50380202_23_dialog_content = "สำหรับสิ่งที่เกิดจากทะเล ทะเลเป็นที่ที่ปลอดภัยที่สุด",
  ui_story_5038_50380202_24_dialog_content = "หา หมายความว่ายังไง",
  ui_story_5038_50380202_25_dialog_content = "ตราบใดที่เข็มทิศยังนำทางเรือ เรือก็จะไม่มีวันสูญหาย และจะมีลมสงบ น้ำนิ่ง และไม่มีอุบัติเหตุเสมอ",
  ui_story_5038_50380202_26_dialog_content = "แต่กลับ...",
  ui_story_5038_50380202_27_dialog_content = "อา แต่เข็มทิศยังคงหายไปใช่ไหม นั่นคือสิ่งที่คุณกำลังจะถาม กัปตัน?",
  ui_story_5038_50380202_28_dialog_content = "มันไม่ได้หายไปเพราะองค์ประกอบ",
  ui_story_5038_50380202_29_dialog_content = "...",
  ui_story_5038_50380202_30_dialog_content = "โจรสลัดกำลังตามล่า Shadowind อย่างร้อนแรง",
  ui_story_5038_50380202_31_dialog_content = "เราทั้งคู่ล้มลงในความโกลาหลทั้งหมดและเราก็ไม่สามารถทำมันได้อีก",
  ui_story_5038_50380202_32_dialog_content = "อย่างที่คุณทราบ พวกอันธพาลเหล่านั้นไม่เคยเข้าถึง The Compass เลย เส้นทางเดินเรือคงไม่ถูกตัดขาดนานขนาดนี้",
  ui_story_5038_50380202_33_dialog_content = "หลังจากนั้นไม่นาน ทั้งโจรสลัดและพวกเราก็ถูกจับได้ <color=#FFB400>พายุที่รุนแรง</color>.",
  ui_story_5038_50380202_34_dialog_content = "วิญญาณทั้งหมดบนเรือหายไป เหลือแต่ Liqing ที่ยังเด็กที่นี่และฉัน",
  ui_story_5038_50380202_35_dialog_content = "นั่นเป็นตอนที่ขาของฉันได้รับบาดเจ็บด้วย",
  ui_story_5038_50380202_36_dialog_content = "ทั้งหมดนี้เกิดขึ้นที่ไหน?",
  ui_story_5038_50380202_37_dialog_content = "ฉันไม่รู้. ฉันไม่รู้ทิศทางของกะลาสีเรือ",
  ui_story_5038_50380202_38_dialog_content = "อย่างไรก็ตาม บางทีมันอาจจะเป็นธรรมชาติทางวิญญาณของปีศาจร้าย แต่ Liqing พาฉันมาที่ Astra",
  ui_story_5038_50380202_39_dialog_content = "เดี๋ยวก่อน... <color=#FFB400>ใจร้าย</color>?",
  ui_story_5038_50380202_40_dialog_content = "นั่นแทบจะไม่สุภาพเลย PlayerName. สหายไม่ใช่สิ่งของ",
  ui_story_5038_50380202_41_dialog_content = "ให้ฉันสอนคุณ กล่าวโดยย่อ พวกอสูรก็คือพวกออโรเรียนเหมือนกับฉันที่มีลักษณะของสัตว์",
  ui_story_5038_50380202_42_dialog_content = "ในขณะที่เรากำลังพูดถึงเรื่องนี้ Tinytail เป็นพี่ชายของฉันจริงๆ",
  ui_story_5038_50380202_43_dialog_content = "ฟ่อ-!",
  ui_story_5038_50380202_44_dialog_content = "โอ้. ฉันคิดว่าฉันเข้าใจแล้ว",
  ui_story_5038_50380202_45_dialog_content = "(โดยพื้นฐานแล้วพวกเขาเป็นชาวออโรเรียนที่มีเลือดกึ่งมนุษย์ใช่ไหม บางทีนี่อาจเป็นเพียงสิ่งที่พวกเขาเรียกว่ากึ่งมนุษย์ในหลงโจว)",
  ui_story_5038_50380202_46_dialog_content = "ตามบันทึกของครอบครัว Lin การสูญเสีย The Compass เป็นเหตุการณ์ที่ไม่เคยมีมาก่อน",
  ui_story_5038_50380202_47_dialog_content = "แม้ว่าฉันจะไม่เคยเห็นมันด้วยตาตัวเอง แต่ฉันได้ยินมาว่ามันเป็นสมบัติล้ำค่า <color=#FFB400>มีชีวิตและตายไปกับเรือของมัน</color>.",
  ui_story_5038_50380202_48_dialog_content = "ยังอยากลองอยู่นะทุกคน แม้ว่าเราจะพบเพียงซากเรือ แต่อย่างน้อยฉันก็จะได้รู้ว่ามันตกอยู่ที่ไหน",
  ui_story_5038_50380202_49_dialog_content = "ฉันไม่ต้องการให้เราต้องพบเจอกับอันตรายแบบที่ Zhong Xu พูดถึง",
  ui_story_5038_50380202_50_dialog_content = "ฉันเข้าใจ. เพื่อประโยชน์ของทุกคนบนเรือ เราไม่สามารถละทิ้งความหวังว่าเราจะพบมัน",
  ui_story_5038_50380202_51_dialog_content = "แม้ว่ากัปตันจะไม่ได้พูดอย่างนั้น ฉันก็ยังอยากจะค้นหาสิ่งนี้",
  ui_story_5038_50380202_52_dialog_content = "ดึกแล้วหาที่ยึดคืนกันดีกว่า",
  ui_story_5038_50380202_53_dialog_content = "ขอให้นอนหลับฝันดี ฉันจะคอยระวังตัวกับลูกเรือ",
  ui_story_5038_50380202_54_dialog_content = "เช่นกัน!",
  ui_story_5038_50380202_55_dialog_content = "เด็กควรนอนหลับสบาย",
  ui_story_5038_50380202_56_dialog_content = "ฉันบอกแล้วไงว่าฉันไม่ใช่เด็ก!",
  ui_story_5038_50380202_57_dialog_content = "และยังไงก็ตาม Tinytail และฉันก็ไม่หลุดลอยไปง่ายๆ ในตอนกลางคืน",
  ui_story_5038_50380202_58_dialog_content = "ให้เขาไปด้วย มิฉะนั้นเขาจะลงเอยด้วยการรบกวนทุกคน",
  ui_story_5038_50380202_59_dialog_content = "เอาล่ะ! ฉันจะไม่ทำอย่างนั้น!",
  ui_story_5038_50380202_60_dialog_content = "ไม่เป็นอะไร. ในกรณีนี้ โปรดตามฉันขึ้นไปบนดาดฟ้าในอีกสักครู่ Liqing",
  ui_story_5038_50380202_61_dialog_content = "มีการทำเตียงในห้องโดยสาร ทุกคนมีพื้นที่ของตัวเอง ถ้าเธอต้องการตามฉันมา ได้โปรด",
