  ui_story_5038_50380301_2_dialog_content = "คร่อกก...",
  ui_story_5038_50380301_3_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_5038_50380301_4_dialog_content = "(ห๊ะ ฟ้าร้องนั่นเหรอ...?)",
  ui_story_5038_50380301_5_dialog_content = "(ฝนตกไหม...?)",
  ui_story_5038_50380301_6_dialog_content = "<color=#e8d9bb>ตุ้บ!!!</color>",
  ui_story_5038_50380301_7_dialog_content = "ว้ากกกก!",
  ui_story_5038_50380301_8_dialog_content = "...?! เกิดอะไรขึ้นน่ะ?",
