  ui_story_5038_50380301_10_dialog_content = "<color=#e8d9bb>เหมียว!!</color>",
  ui_story_5038_50380301_11_dialog_content = "ที่นั้นที่นั้น. ไม่มีอะไรต้องกลัว",
  ui_story_5038_50380301_12_dialog_content = "ขอโทษที่ทำให้คุณตื่น เพื่อนสาว",
  ui_story_5038_50380301_13_dialog_content = "Yixin, Yimeng และ Yinuo... พวกเขาอยู่กับฉันมาทั้งชีวิต และยังรอดชีวิตจากเหตุการณ์ในอดีต Shadowind...",
  ui_story_5038_50380301_14_dialog_content = "สภาพอากาศเช่นนี้ทำให้ความทรงจำอันน่าหวาดเสียวกลับคืนมาสำหรับพวกเขา",
