  ui_story_5038_50380301_17_dialog_content = "ทุกคนตื่นยัง? คุณโอเคไหม?",
  ui_story_5038_50380301_18_dialog_content = "จิ่วได้ยินเป็นคนแรก ฉันไปไหนมาไหนกับเธอ ปลุกใครก็ตามที่นอนหลับได้ผ่านแร็กเกต",
