  ui_story_5038_50380302_5_dialog_content = "นำสิ่งของและสินค้าหนักไปที่ท้ายเรือเพื่อให้เรือสมดุลกะลาสี!",
  ui_story_5038_50380302_6_dialog_content = "ใช่!",
