  ui_story_5038_50380402_61_dialog_content = "ฉันได้พบกับกลุ่มสัตว์สามตัวที่แปลกประหลาดมาก: หนูที่ลังเล ลิงโง่เขลา และกระต่ายเจ้าเล่ห์",
