  ui_story_5038_50380402_63_dialog_content = "ทั้งสามปรากฏตัวด้วยรูปแฉกหยิน-หยางที่ผสมกันซึ่งดูเหมือนว่าพวกเขาทั้งหมดจะบอกใบ้ในสิ่งเดียวกัน",
  ui_story_5038_50380402_64_dialog_content = "หนู ลิง กระต่าย...?",
  ui_story_5038_50380402_65_dialog_content = "แล้วการตีความของคุณคืออะไร?",
  ui_story_5038_50380402_66_dialog_content = "ฉันไม่ใช่ผู้เชี่ยวชาญ แต่ข้อสรุปของฉันคือพวกเขาอ้างถึงสิ่งที่เกี่ยวข้องกับการแลกเปลี่ยนสินค้าหนึ่งกับอีกสินค้าหนึ่ง",
  ui_story_5038_50380402_67_dialog_content = "\"สิ่งที่เป็นมายากลายเป็นจริง เมื่อความจริงกลายเป็นมายา\" โดยพื้นฐานแล้วมันกำลังบอกเราว่า <color=#FFB400>แทนที่</color> ที่เราเสียไป",
  ui_story_5038_50380402_68_dialog_content = "แทนที่...?",
  ui_story_5038_50380402_69_dialog_content = "โอ้! ฉันคิดว่าฉันเข้าใจแล้ว!",
  ui_story_5038_50380402_70_dialog_content = "ประเพณีในบ้านเกิดของเราคือการตั้งชื่อส่วนสำคัญของลำเรือตามสัตว์ 12 นักษัตร",
  ui_story_5038_50380402_71_dialog_content = "เราขออธิษฐานให้สิ่งนี้นำความโชคดีมาให้เราแล่นข้ามทะเลอย่างมั่นคงราวกับสัตว์ที่เหยียบบนบก",
  ui_story_5038_50380402_72_dialog_content = "หลายส่วนของตัวเรือได้รับความเสียหายจากพายุเมื่อคืนนี้",
  ui_story_5038_50380402_73_dialog_content = "รวมทั้งหางหนูที่ท้ายเรือ และหัวลิงที่หัวเรือ อันแรกหายเกลี้ยง อีกอันเสียหาย",
  ui_story_5038_50380402_74_dialog_content = "แต่ราวบันไดหูกระต่ายไม่เป็นไร",
