  ui_story_5038_50380602_59_dialog_content = "มาเถอะเจ้าหญิง ตามล่าหาสมบัติของเราสองคนกันเถอะ",
  ui_story_5038_50380602_60_dialog_content = "หางของหนูตัวน้อยนี้จะไม่ซ่อนอยู่อีกต่อไป",
  ui_story_5038_50380602_61_dialog_content = "<color=#e8d9bb>คาว! คาว!</color>",
  ui_story_5038_50380602_62_dialog_content = "ให้อินทผาลัมหวานๆ หน่อย วัว!",
  ui_story_5038_50380602_63_dialog_content = "ขอเมล็ดแตงโมหวานอร่อย คาว!",
  ui_story_5038_50380602_64_dialog_content = "ฉันรู้ว่าฉันรู้ว่า. คุณจะได้รับการปฏิบัติของคุณ คุณหาเจอไหม?",
  ui_story_5038_50380602_65_dialog_content = "นั่นมัน...?",
  ui_story_5038_50380602_66_dialog_content = "ดูเหมือนหางมาก... มันต้องแบบนี้สิ!",
  ui_story_5038_50380602_67_dialog_content = "ใช่! ดูเหมือนว่าคุณพูดถูกจริงๆ",
  ui_story_5038_50380602_68_dialog_content = "โชคดีที่คุณสองคนมองเห็นมันท่ามกลางโคลนตม",
  ui_story_5038_50380602_69_dialog_content = "คุณจะได้รับอินทผลัมแสนอร่อยและเมล็ดแตงโมในไม่ช้า!",
  ui_story_5038_50380602_70_dialog_content = "รับมันเจ้าหญิง",
  ui_story_5038_50380602_71_dialog_content = "ไปนำไปให้กัปตัน Yuebai",
  ui_story_5038_50380701_1_dialog_content = "(หลังจาก Dantang มอบ \"หางหนู\" ให้ Yuebai...)",
  ui_story_5038_50380701_2_dialog_content = "(การซ่อมเรือดำเนินไปได้ด้วยดี และเสากระโดงก็เกือบจะได้กลับคืนมาแล้ว)",
  ui_story_5038_50380701_3_dialog_content = "(มันแล่นได้ราบรื่นกว่ามาก เกือบเหมือนไม่เคยมีอุบัติเหตุเกิดขึ้น)",
  ui_story_5038_50380701_4_dialog_content = "(ก็แค่...)",
  ui_story_5038_50380701_5_dialog_content = "สายลมเปลี่ยนไป เตรียมหยุดพายและทิ้งสมอ!",
  ui_story_5038_50380701_6_dialog_content = "ใช่!",
  ui_story_5038_50380701_7_dialog_content = "(ยกเว้นเรายังต้องหยุดกระทันหันเป็นระยะๆ)",
  ui_story_5038_50380701_8_dialog_content = "คุณดูกังวลชายหนุ่ม",
  ui_story_5038_50380701_9_dialog_content = "ฉันไม่. ฉันเดาว่า... ฉันเชื่อการตัดสินใจของ Yuebai",
  ui_story_5038_50380701_10_dialog_content = "ไม่จำเป็นต้องซ่อนความรู้สึกของคุณ สงสัยเราจะคิดเหมือนกัน",
  ui_story_5038_50380701_11_dialog_content = "(เขามองผ่านฉัน...)",
  ui_story_5038_50380701_12_dialog_content = "เรากำลังมุ่งหน้าไปยังตำแหน่งที่ทราบครั้งสุดท้ายของ The Compass ด้วยความช่วยเหลือของแผนภูมิการเดินเรือ",
  ui_story_5038_50380701_13_dialog_content = "แต่เรือยังคงอยู่ในสภาพที่ล่อแหลม และการซ่อมแซมชั่วคราวก็เหมือนการฉาบปูนมากกว่าการรักษา",
  ui_story_5038_50380701_14_dialog_content = "การเดินเรือเป็นทักษะที่แม่นยำมากและมีความผิดพลาดเพียงเล็กน้อย",
  ui_story_5038_50380701_15_dialog_content = "การสวดอ้อนวอนเพียงอย่างเดียวไม่ได้รับประกันว่าสิ่งต่างๆ จะราบรื่น",
  ui_story_5038_50380701_16_dialog_content = "... อย่างไรก็ตาม มันเป็นแค่ความกังวลเล็กน้อยของฉัน",
  ui_story_5038_50380701_17_dialog_content = "อย่าเก็บมาใส่ใจ",
  ui_story_5038_50380701_18_dialog_content = "แน่นอน. ฉันจะพยายามรวบรวมตัวเอง และ Zhong Xu คุณจำไว้ว่าอย่ากังวลตัวเองมากเกินไป!",
  ui_story_5038_50380701_19_dialog_content = "Shadowind ประสบกับอุปสรรคทุกรูปแบบ แต่ก็ยังสามารถมาถึง Astra ได้อย่างปลอดภัย ไม่มีทางที่เธอจะปล่อยให้พวกเราตายในทะเล",
  ui_story_5038_50380701_20_dialog_content = "ความเงียบ!",
  ui_story_5038_50380701_21_dialog_content = "อะ-อะไรนะ!",
  ui_story_5038_50380701_22_dialog_content = "... ขออภัย ฉันแสดงปฏิกิริยาเกินจริง",
  ui_story_5038_50380701_23_dialog_content = "ในบ้านเกิดของฉัน การพูดเรื่องแบบนี้ถือเป็นเรื่องต้องห้ามเมื่อใกล้จะถึงปีใหม่",
  ui_story_5038_50380701_24_dialog_content = "ฉันรู้ว่ามันเป็นเพียงธรรมเนียมเล็กๆ น้อยๆ ที่ไม่เป็นอันตราย แต่ฉันหวังว่าคุณจะเข้าใจ",
  ui_story_5038_50380701_25_dialog_content = "ฉันขอโทษ ฉันขอลาไปก่อน",
  ui_story_5038_50380701_26_dialog_content = "(หมายความว่า...พูดถึงความตายเป็นข้อห้าม?)",
  ui_story_5038_50380701_27_dialog_content = "คุณไม่ค่อยเห็น Zhong Xu ทำงานหนักมากนัก",
  ui_story_5038_50380701_28_dialog_content = "ฉันเดาว่าเขากังวลเกี่ยวกับการทำผิดพลาดเหมือนเมื่อหกเดือนก่อน",
  ui_story_5038_50380701_29_dialog_content = "PlayerName, ขอมือหน่อยได้ไหม?",
  ui_story_5038_50380701_30_dialog_content = "ฉันแค่ค่อยๆ เคลื่อนเรือชูชีพไม้เล็กๆ ลำนี้ไปที่ราง",
  ui_story_5038_50380701_31_dialog_content = "ฮะ? รอก่อน! ไม่ใช่แค่นี้โดยพื้นฐานแล้ว <color=#FFB400>ขโมย</color>?",
  ui_story_5038_50380701_32_dialog_content = "อย่าดราม่านะเหมียว",
  ui_story_5038_50380701_33_dialog_content = "ดูสิ กัปตันและ Zhong Xu อยู่ที่นั่นเพื่อหารือเกี่ยวกับการป้องกันการซึมและการรั่วไหล",
  ui_story_5038_50380701_34_dialog_content = "ฉันไม่สามารถขัดจังหวะพวกเขาได้",
  ui_story_5038_50380701_35_dialog_content = "แต่คุณตั้งใจจะทำอะไรกับเรือชูชีพ?",
