  ui_story_5038_50380701_37_dialog_content = "ไม่มีทาง! มันอันตรายเกินไป!",
  ui_story_5038_50380701_38_dialog_content = "ฟังฉันนะ, PlayerName. ถ้า Shadowind เป็นคน ตอนนี้เธอคงป่วย",
  ui_story_5038_50380701_39_dialog_content = "โรคต้องรักษาให้ถูกวิธี สมุนไพรบางชนิดหาได้ง่าย",
  ui_story_5038_50380701_40_dialog_content = "ในขณะที่บางต้นเติบโตครึ่งทางบนหน้าผาสูงชัน ไกลเกินเอื้อม",
  ui_story_5038_50380701_41_dialog_content = "หัวลิงเสียหาย และไม่มีการเปลี่ยนที่เหมาะสมบนเครื่อง",
  ui_story_5038_50380701_42_dialog_content = "ต้องออกทะเลเพื่อรักษาโรค",
  ui_story_5038_50380701_43_dialog_content = "ทะเล?? คุณคิดว่าคุณจะพบบางสิ่งที่นั่นโดยที่คุณไม่พบมันบนเรือด้วยซ้ำ?",
  ui_story_5038_50380701_44_dialog_content = "ฉันไม่รู้ว่าคุณสังเกตเห็นหรือเปล่า แต่มีสิ่งต่างๆ มากมายลอยอยู่รอบๆ ที่นี่",
  ui_story_5038_50380701_45_dialog_content = "เศษเหล่านี้ล้วนเป็นซากเรือในอดีตที่ไม่มีใครรู้จัก สูญหายไปในทะเลใครจะรู้เมื่อไหร่",
  ui_story_5038_50380701_46_dialog_content = "ถ้าฉันสามารถหา \"หัวลิง\" อีกลำจากเรือเหล่านี้ได้ แน่นอนว่านั่นจะช่วยแก้ปัญหาของ Shadowind ได้",
  ui_story_5038_50380701_47_dialog_content = "เราจะเคลื่อนที่เร็วขึ้นมากเมื่อยกใบเรือได้แล้ว! หายห่วงเรื่อง \"หูกระต่าย\" ได้เลย!",
  ui_story_5038_50380701_48_dialog_content = "คุณมีประเด็น แต่สิ่งนี้เป็นไปได้จริงหรือ",
  ui_story_5038_50380701_49_dialog_content = "มันเหมือนกับการงมเข็มในมหาสมุทร นั่นคือมหาสมุทร",
  ui_story_5038_50380701_50_dialog_content = "เป็นไปได้ถ้าฉันบอกว่ามันเป็น PlayerName. ฉันเป็นศัตรูที่นี่หลังจากทั้งหมด",
  ui_story_5038_50380701_51_dialog_content = "ของฉัน <color=#FFB400>เพื่อนทางทะเล</color> จะให้หมายสำคัญและสัญญาณแก่ข้าพเจ้า",
  ui_story_5038_50380701_52_dialog_content = "คุณเป็นจริงหรือไม่",
  ui_story_5038_50380701_53_dialog_content = "แน่นอน. ฉันมักจะคุยกับพวกเขาเมื่อฉันออกทะเล",
  ui_story_5038_50380701_54_dialog_content = "ถ้าฉันขอความช่วยเหลือ พวกเขาจะจัดให้",
  ui_story_5038_50380701_55_dialog_content = "รวมถึงช่วยคุณค้นหา \"หัวลิง\" ของเรือลำอื่น?",
  ui_story_5038_50380701_56_dialog_content = "แต่... พวกเขาจะรู้ได้อย่างไรว่าสิ่งนั้นหน้าตาเป็นอย่างไร?",
  ui_story_5038_50380701_57_dialog_content = "ไม่ต้องกังวลเกี่ยวกับเรื่องนั้น ฉันสามารถอธิบายให้พวกเขาฟังได้",
  ui_story_5038_50380701_58_dialog_content = "ยังไงก็ขอบคุณที่ช่วย PlayerName! ฉันสามารถรับได้จากที่นี่!",
  ui_story_5038_50380701_59_dialog_content = "ฉันยังกังวลเล็กน้อย ฉันจะคอยจับตาดูคุณทางกระแสจิต",
