  ui_story_5038_50380701_61_dialog_content = "ตกลงตกลง. อดใจรอฟังข่าวดีของฉันกันได้เลย!",
  ui_story_5038_50380701_62_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50380701_63_dialog_content = "ย๊าาาาาา!!!",
  ui_story_5038_50380701_64_dialog_content = "อะไร มันคืออะไร?! ลี่ชิง!",
  ui_story_5038_50380701_65_option_content = "บูสต์พลัง!",
  ui_story_5038_50380701_66_dialog_content = "(น้ำมาก! น้ำมากเกินไป! น้ำ น้ำทุกที่...!)",
