  ui_story_5038_50380701_69_dialog_content = "เดี๋ยวก่อน คุณไม่ได้บอกว่าคุณกลัวน้ำใช่ไหม",
  ui_story_5038_50380701_70_dialog_content = "ก็แหม! แมวไม่ชอบน้ำแทบจะไม่เป็นข่าว!",
  ui_story_5038_50380701_71_dialog_content = "(โอ้ Liqing ผู้น่าสงสารตัวสั่นอย่างรุนแรง อุบัติเหตุเมื่อหกเดือนก่อนคงสร้างบาดแผลลึกให้กับเขา)",
  ui_story_5038_50380701_72_dialog_content = "ค-กลับมาเร็วเข้า! พยายามอย่าขยับมากเกินไป ฉันจะยกเธอและเรือกลับขึ้นมา...",
