  ui_story_5038_50380701_74_dialog_content = "เหมียว...",
  ui_story_5038_50380701_75_dialog_content = "คุณกำลังคิดอะไรอยู่ ทำไมคุณถึงยืนกรานที่จะลงไปเมื่อคุณกลัวน้ำมาก?",
  ui_story_5038_50380701_76_dialog_content = "คิดว่าตัวเองทำได้...",
  ui_story_5038_50380701_77_dialog_content = "อืม...ยังไงก็ตาม PlayerNameตอนนี้เราอยู่ที่นี่ ฉันเกรงว่าฉันต้องขอความช่วยเหลือ",
  ui_story_5038_50380701_78_dialog_content = "ให้ฉันเดา: คุณจะไม่เป็นไรถ้าฉันไปกับคุณ?",
  ui_story_5038_50380701_79_dialog_content = "ต่างคนต่างยุ่งอยู่กับการซ่อมเรือ เรามาเร็ว ๆ นี้กันเถอะ",
  ui_story_5038_50380701_80_dialog_content = "ได้เลยค่ะ!",
  ui_story_5038_50380701_81_dialog_content = "(ก่อนออกเดินทาง ฉันน่าจะรีเฟรชหน่วยความจำเกี่ยวกับโปรโตคอลความปลอดภัย...)",
