  ui_story_5038_50380702_10_dialog_content = "ฉันไม่ใช่แค่แมวอีกต่อไป เห็นได้ชัดว่าฉันไม่ชอบอะไรแบบนี้!",
  ui_story_5038_50380702_11_dialog_content = "(น่ารัก...)",
  ui_story_5038_50380702_12_dialog_content = "เมื่อพูดถึงเรื่องนี้ มีเพื่อนคู่แค้นคนไหนบ้างที่คุณจากมา PlayerName?",
