  ui_story_5038_50380702_16_dialog_content = "คุณรู้ไหมว่า Tinytail เป็นพี่ชายของฉัน",
  ui_story_5038_50380702_17_dialog_content = "ย-อะไรของคุณ...?!",
  ui_story_5038_50380702_18_dialog_content = "นั่นเป็นเหตุผลที่ Tianxian เรียกคุณว่าคิตตี้เสมอ ?? เพราะคุณเป็นคนหนึ่งจริง ๆ ?",
  ui_story_5038_50380702_19_dialog_content = "ฉัน-มันหยาบคายมากที่เขาเรียกฉันแบบนั้น",
  ui_story_5038_50380702_20_dialog_content = "แต่คุณพูดถูก ในบ้านเกิดของฉัน อสูรเป็นสัตว์ที่ปลูกฝังเป็นออโรเรียน",
  ui_story_5038_50380702_21_dialog_content = "ตระกูลที่มีอิทธิพลในหลงโจวที่สนับสนุนสันติภาพมักจะเชิญเพื่อนรักมาที่บ้านในฐานะแขก",
  ui_story_5038_50380702_22_dialog_content = "มีหน้าที่เหมือนรีเทนเนอร์",
  ui_story_5038_50380702_23_dialog_content = "นั่นคือวิธีที่ฉันรู้จัก Lin Guildmaster",
  ui_story_5038_50380702_24_dialog_content = "ดูเหมือนว่าเขาจะเป็นคนที่ให้ความสำคัญกับมิตรภาพจริงๆ",
  ui_story_5038_50380702_25_dialog_content = "เอ่อ... พูดตามตรง ฉันแทบไม่เข้าใจคำว่าธุรกิจที่คนแก่พูดพล่ามเลยสักคำ",
  ui_story_5038_50380702_26_dialog_content = "ครอบครัว Lins เชิญฉันไปที่คฤหาสน์ของพวกเขาเพราะพวกเขาต้องการให้ฉันช่วยพวกเขา <color=#FFB400>ดูแลปลาของพวกเขา</color>.",
  ui_story_5038_50380702_27_dialog_content = "ฉันรู้ว่าทุกคนคิดว่าแมวกินปลา แต่ปลาทะเลเป็นเพื่อนของฉัน",
  ui_story_5038_50380702_28_dialog_content = "คุณหมายความว่าคุณสามารถสื่อสารกับงู?",
  ui_story_5038_50380702_29_dialog_content = "มากหรือน้อย. ก็จริงอยู่ แต่ดูเมื่อคืนก่อน ช่วยอะไรไม่ได้เลย ท่ามกลางวิกฤต...",
