  ui_story_5038_50380702_36_dialog_content = "ตรวจสอบออก PlayerName.",
  ui_story_5038_50380702_37_dialog_content = "T-ช่างเหลือเชื่อ!",
  ui_story_5038_50380702_38_dialog_content = "เกือบจะเหมือนเวทมนตร์!",
  ui_story_5038_50380702_39_dialog_content = "บอกคุณว่าเพื่อนทะเลของฉันจะผ่านมา",
