  ui_story_5038_50380702_49_dialog_content = "PlayerName, ลี่ชิง! สิ่งที่คุณทำนั้นเสี่ยงมาก!",
  ui_story_5038_50380702_50_dialog_content = "คุณคิดถึงผลที่ตามมาก่อนที่คุณจะจากไปหรือไม่?",
