  ui_story_5038_50380702_53_dialog_content = "ลูกรอก?!",
  ui_story_5038_50380702_54_dialog_content = "เห็นได้ชัดว่ามันถูกแช่อยู่ในน้ำทะเล แต่ควรซ่อมแซมได้หลังจากทำความสะอาดอย่างดี",
