  ui_story_5038_50380801_1_dialog_content = "(ความเร็วของเรืออาจกลับมาเป็นปกติ แต่สถานะของลำเรือยังน่าเป็นห่วงอยู่เล็กน้อย)",
  ui_story_5038_50380801_2_dialog_content = "(ทุกคนทำงานกันไม่หยุด ราวกับว่า Shadowind จะจมหากหยุดแม้แต่วินาทีเดียว)",
  ui_story_5038_50380801_3_dialog_content = "(ดูเหมือนเราคิดว่าการหมดแรงเป็นยาแก้กังวล)",
  ui_story_5038_50380801_4_dialog_content = "แล่นไปอีกหน่อยก็ถึงท่าเรือแล้ว ลูกเรือ สายลมเปลี่ยนไป",
