  ui_story_5038_50380801_11_dialog_content = "ใช่!",
  ui_story_5038_50380801_12_dialog_content = "ฉันหวังว่าหลักสูตรของเราจะจัดขึ้น ฉันกำลังออกไปที่สะพานเพื่อตรวจสอบสิ่งต่างๆ",
  ui_story_5038_50380801_13_dialog_content = "(Yuebai เคลื่อนไหวตลอดเวลา เธอไม่หยุดแม้แต่จะพูด)",
  ui_story_5038_50380801_14_dialog_content = "(เธอมีเรื่องต้องคิดมากกว่าพวกเราที่เหลือ และนั่นทำให้เธอกดดันมากขึ้นอย่างเห็นได้ชัด)",
  ui_story_5038_50380801_15_dialog_content = "(บางทีรอยเท้าของเธออาจอุดช่องโหว่บางอย่างใน The Shadowind ได้)",
  ui_story_5038_50380801_16_dialog_content = "อีกหนึ่งมุมมอง...",
