  ui_story_5038_50380801_22_dialog_content = "(หัวลิงเมื่อวานนี้เป็นเพียงส่วนยอดของภูเขาน้ำแข็ง ตอนนี้เราเห็นซากของซากเรือนับไม่ถ้วน ทั้งหมดที่หายไปในทะเลที่นี่)",
  ui_story_5038_50380801_23_dialog_content = "(ตานตังนั่งอยู่ข้างเรือตลอดเวลา มองออกไปในทะเล นับเศษไม้ที่ลอยไปแต่ละชิ้น)",
  ui_story_5038_50380801_24_dialog_content = "(มีเพียงเราเป็นพยานถึงเศษซากของผู้ที่ยอมจำนนต่อคลื่น)",
