  ui_story_5038_50380801_26_dialog_content = "หากมีซากปรักหักพังขวางทาง แสดงว่าเรามาถูกทางแล้ว",
  ui_story_5038_50380801_27_dialog_content = "คุณไม่คิดว่ามหาสมุทรที่รกร้างและว่างเปล่านั้นน่ากลัวกว่ามากเหรอ?",
  ui_story_5038_50380801_28_dialog_content = "(หลี่ชิงเดินผ่านไป ปลาแห้งห้อยลงมาจากปากของเขา)",
  ui_story_5038_50380801_29_dialog_content = "(เขาคอยช่วยเหลือ แต่ดูเหมือนว่าจะมีท่าทีเมินเฉยอยู่เสมอ)",
  ui_story_5038_50380801_30_dialog_content = "(บางทีเขาอาจจะพยายามสร้างเกมจากงานทั้งหมด)",
  ui_story_5038_50380801_31_dialog_content = "อ่า... ฉันเหนื่อยแล้ว",
  ui_story_5038_50380801_32_dialog_content = "น้ำในตู้สินค้าจะไหลเข้ามาเรื่อยๆ ไม่ว่าคุณจะประกันตัวเท่าไรก็ตาม",
  ui_story_5038_50380801_33_dialog_content = "ตัดสินใจมาร่วมงานกับเรา PlayerName?",
