  ui_story_5038_50380801_35_dialog_content = "(Tianxian เป็นตัวตนปกติของเขา แค่ช่างพูดไม่หยุด)",
  ui_story_5038_50380801_36_dialog_content = "และค่อนข้างถูกต้อง ไม่ดีที่จะทำให้ตัวเองเหนื่อย",
  ui_story_5038_50380801_37_dialog_content = "เมื่อการประกันตัวของวันนี้เสร็จสิ้น จะมีมากขึ้นในวันพรุ่งนี้",
  ui_story_5038_50380801_38_dialog_content = "เราต้องอดทนมากกว่ามหาสมุทรในการเดินทางครั้งนี้",
  ui_story_5038_50380801_39_dialog_content = "คุณดูเหมือนจะมีคำพูดสำหรับทุกโอกาส",
  ui_story_5038_50380801_40_dialog_content = "แน่นอน. ฉันต้องโน้มน้าวใจตัวเองให้เผชิญกับวันที่ไม่สิ้นสุดเหล่านี้ด้วยความใจเย็น",
  ui_story_5038_50380801_41_dialog_content = "คุณวีลแชร์คือที่พึ่งสุดท้ายของเรา ถ้าเขายังไม่พร้อมทำงาน สถานการณ์ก็ไม่เลวร้ายขนาดนั้น",
  ui_story_5038_50380801_42_dialog_content = "อย่าเข้าใจผิดว่าความพิการคือความเกียจคร้าน",
  ui_story_5038_50380801_43_dialog_content = "เฮ้ดูสิว่าใคร! ท่านจง!",
  ui_story_5038_50380801_44_dialog_content = "เราไม่ค่อยเห็นคุณสูดอากาศบนดาดฟ้า!",
  ui_story_5038_50380801_45_dialog_content = "ไม่จำเป็นต้องปฏิบัติต่อฉันเหมือนขุนนางบางคน ฉันไม่มีพลังแบบนั้นบนบกและบนเรือแม้แต่น้อย",
  ui_story_5038_50380801_46_dialog_content = "นายถ่อมตัวเกินไป เสือที่ไม่มีฟันยังคงเป็นสัตว์ที่น่าเกรงขามและควรค่าแก่การเคารพ อดีตนายพลที่ยิ่งใหญ่น้อยกว่ามาก",
  ui_story_5038_50380801_47_dialog_content = "คุณเป็นผู้เชี่ยวชาญในการดูหมิ่นอย่างแท้จริง",
  ui_story_5038_50380801_48_dialog_content = "ที่จริงฉันมีความคิดที่อาจช่วยบรรเทาปัญหาบางอย่างในปัจจุบันของเราได้",
  ui_story_5038_50380801_49_dialog_content = "แต่ฉันต้องการความช่วยเหลือจากคุณเพื่อให้มันทำงาน",
  ui_story_5038_50380801_50_dialog_content = "จริงหรือ มันคืออะไร?",
  ui_story_5038_50380801_51_dialog_content = "ฉันยินดีที่จะช่วย!",
  ui_story_5038_50380801_52_dialog_content = "ใครจะรู้สึกเป็นเกียรติที่ได้ช่วยเหลือสุภาพบุรุษที่ฉลาดและมีความสามารถ!",
