  ui_story_5038_50380801_57_dialog_content = "ไม้ที่ลอยมาไม่สามารถใช้งานได้ทั้งหมด กรุณารวบรวมเฉพาะที่ฉันชี้ให้เห็น",
  ui_story_5038_50380801_58_dialog_content = "ฮะ? พวกเขาแตกต่างกันอย่างไร?",
  ui_story_5038_50380801_59_dialog_content = "ไม่เป็นไรหรอก ทำตามที่เขาบอกตอนนี้ ฉันแน่ใจว่าเขารู้ว่าเขากำลังพูดถึงอะไร",
  ui_story_5038_50380801_60_dialog_content = "มาดูกันว่าเราจะดึงตาข่ายออกจากลูกเรือคนหนึ่งได้หรือไม่",
  ui_story_5038_50380801_61_dialog_content = "ลาก!",
