  ui_story_5038_50380801_68_dialog_content = "ลี่ชิง? ไม่ นี่ไม่ใช่สำหรับ—",
  ui_story_5038_50380801_69_dialog_content = "ฉันขอให้พวกเขาช่วยฉันรวบรวมมัน",
