  ui_story_5038_50380901_42_dialog_content = "มันเป็นธุรกิจของฉันที่จะดูแลคุณ คุณไม่รู้หรอกว่ามันลมแรงแค่ไหน?",
  ui_story_5038_50380901_43_dialog_content = "ลมกระโชกแรงเพียงครั้งเดียวก็สามารถพัดพาคุณออกไปได้ ใครจะไปรู้",
  ui_story_5038_50380901_44_dialog_content = "กลับมาที่กระท่อมกับฉัน",
  ui_story_5038_50380901_45_dialog_content = "เมี้ยว!",
  ui_story_5038_50380901_46_dialog_content = "*หอบ* เชี่ย มันวิ่งได้จริงๆ",
  ui_story_5038_50380901_47_dialog_content = "ไม่ต้องกังวล. สัตว์มีสัญชาตญาณที่เฉียบแหลมกว่าเรามาก",
  ui_story_5038_50380901_48_dialog_content = "เป็นเราที่ต้องพึ่งพาพวกเขาเมื่อภัยที่แท้จริงพื้นผิว",
