  ui_story_5038_50380901_73_dialog_content = "ในพายุ?",
  ui_story_5038_50380901_74_dialog_content = "มันอันตรายเกินไป! เราจะไม่สามารถควบคุมเรือได้!",
  ui_story_5038_50380901_75_dialog_content = "ไม่ต้องพูดถึง Eclipsites อีกมากที่สามารถขึ้นเรือได้เหมือนเมื่อก่อน!",
