  ui_story_5038_50380901_79_dialog_content = "แต่กลับ...",
  ui_story_5038_50380901_80_dialog_content = "เราต้องใช้ประโยชน์จากลมทุก ๆ ส่วนที่เรามี แม้แต่ในพายุก็ตาม",
  ui_story_5038_50380901_81_dialog_content = "สำหรับ Eclipsites เป็นผู้บุกรุกที่ควรกลัวที่จะก้าวขึ้นเรือลำนี้ ไม่ใช่พวกเรา",
  ui_story_5038_50380901_82_dialog_content = "เราไม่ขาดแคลนแขกบนเครื่องที่กำลังมองหาการดำเนินการ",
