  ui_story_5038_50380901_84_dialog_content = "อ๊ะ อะไรก็ได้! ฉันเป็นแค่มือฉมัง เป็นคำสั่งของกัปตันนั่นเอง",
  ui_story_5038_50380901_85_dialog_content = "ไม่เป็นอะไร. เข้าประจำที่ท้ายเรือ",
