  ui_story_5038_50381001_1_dialog_content = "(พายุได้เขย่า Shadowind ตลอดทั้งวัน)",
  ui_story_5038_50381001_2_dialog_content = "(เราพบปัญหามากมายตั้งแต่เมาเรือ ไปจนถึงโรงเรียนปลาโจมตี ไปจนถึง Eclipsites)",
  ui_story_5038_50381001_3_dialog_content = "(แต่เมื่อครู่นี้ เสียงพายุที่พัดกระหน่ำจนน่าสะพรึงกลัวในใบเรือเริ่มเบาบางลงมาก)",
