  ui_story_5038_50381001_7_dialog_content = "ใช่ ส่วนที่ยากที่สุดของการเดินทางสิ้นสุดลงแล้ว",
  ui_story_5038_50381001_8_dialog_content = "ความปั่นป่วนเล็กน้อยจากนี้ไป ไม่มีอะไรป้องกันไม่ได้แก้ไข",
  ui_story_5038_50381001_9_dialog_content = "ขอบคุณพระเจ้าที่มันจบลงแล้ว",
  ui_story_5038_50381001_10_dialog_content = "ฉันจะอ้วกอวัยวะทั้งหมดของฉัน ถ้าเรือยังคงโคลงเคลง",
  ui_story_5038_50381001_11_dialog_content = "คุณโอเคไหม เทียนเซียน? คุณดูค่อนข้างหยาบ",
  ui_story_5038_50381001_12_dialog_content = "ฉันกำลังห้อยอยู่ในนั้น การได้รับอากาศบริสุทธิ์บนดาดฟ้าช่วยได้มาก",
  ui_story_5038_50381001_13_dialog_content = "กัปตันยังไม่ถึงเวลาทานอาหารเหรอ?",
  ui_story_5038_50381001_14_dialog_content = "เราต้องได้รับบางอย่างในตัวเราหลังจากวันทั้งวันในพายุที่ปั่นป่วน",
