  ui_story_5038_50381001_16_dialog_content = "เดคแฮนด์ บอกแม่ครัวในครัวให้เตรียมอาหารเย็น",
  ui_story_5038_50381001_17_dialog_content = "ได้สิ",
  ui_story_5038_50381001_18_dialog_content = "อย่างไรก็ตาม กัปตัน เรากำลังขาดแคลนเสบียง ดังนั้นเราต้องปันส่วนพวกมัน",
