  ui_story_5038_50381002_10_dialog_content = "โอเค ตอนนี้ทุกอย่างควรจะเรียบร้อยดี",
  ui_story_5038_50381002_11_dialog_content = "มันเรียกปลาตัวอื่นออกมา?",
  ui_story_5038_50381002_12_dialog_content = "ได้. Serpentfish อยู่ในโรงเรียนเสมอ และความรู้สึกเป็นหนึ่งเดียวของพวกมันก็แข็งแกร่ง",
  ui_story_5038_50381002_13_dialog_content = "ทั้งโรงเรียนจะช่วยเหลือสมาชิกที่มีปัญหา",
  ui_story_5038_50381002_14_dialog_content = "ไม่ควรโกรธงูในทะเล",
  ui_story_5038_50381002_15_dialog_content = "แพ็คความคิด... ช่างเป็นลักษณะเฉพาะ",
  ui_story_5038_50381002_16_dialog_content = "ขอบคุณสำหรับคำเตือน Liqing ท่าน Zhong",
  ui_story_5038_50381002_17_dialog_content = "เราขออภัยในความสะเพร่าของเรา",
  ui_story_5038_50381002_18_dialog_content = "ไม่เป็นไร. เราทุกคนอยู่ในเรือลำเดียวกัน อย่างแท้จริง.",
  ui_story_5038_50381002_19_dialog_content = "ไม่มีอันตรายใด ๆ เกิดขึ้น ดังนั้นอย่าลืมว่ามันเกิดขึ้น",
  ui_story_5038_50381002_20_dialog_content = "ไม่น่าเชื่อว่าปลาช่อนจะอยู่ในน่านน้ำเหล่านี้ อย่าบอกนะว่าพวกเขาจะโจมตีเราอีกครั้ง...",
  ui_story_5038_50381002_21_dialog_content = "เราคงไม่สามารถต้านทานคลื่นลูกอื่นได้...",
  ui_story_5038_50381002_22_dialog_content = "<color=#e8d9bb>วันถัดไป</color>",
  ui_story_5038_50381002_23_dialog_content = "งูอีกตัว! ปล่อยเดี๋ยวนี้!",
  ui_story_5038_50381002_24_dialog_content = "ฉันรู้ว่าฉันรู้ว่า. ไม่ใช่ว่านี่เป็นครั้งแรก",
  ui_story_5038_50381002_25_dialog_content = "เฮ้อ... พวกมันหยุดทำลายโอกาสในการจับปลาของเราไม่ได้หรือ?",
  ui_story_5038_50381002_26_dialog_content = "ตัวที่เจ็ด...",
  ui_story_5038_50381002_27_dialog_content = "นี่ไง ยูไป๋!",
  ui_story_5038_50381002_28_dialog_content = "พวกเขาส่งฉันไปบอกคุณว่าอาหารกลางวันพร้อมแล้ว",
  ui_story_5038_50381002_29_dialog_content = "คาดเดาอะไร วันนี้เราจะกินอะไรดี! แม้ว่าทุกอย่างจะปรุงด้วยปลา",
  ui_story_5038_50381002_30_dialog_content = "พวกนายลุยเลย ฉันจะรอสักครู่",
  ui_story_5038_50381002_31_dialog_content = "หา? ทำไมล่ะ?",
  ui_story_5038_50381002_32_dialog_content = "มีอะไรรบกวนคุณหรือเปล่า?",
  ui_story_5038_50381002_33_dialog_content = "มีและอยากจะหามาให้คลายกังวล",
  ui_story_5038_50381002_34_dialog_content = "ว่าไง",
  ui_story_5038_50381002_35_dialog_content = "งูเหล่านี้มีพฤติกรรมที่ผิดปกติอย่างมาก",
  ui_story_5038_50381002_36_dialog_content = "พวกมันเป็นสายพันธุ์อพยพที่เดินทางระหว่างชายฝั่งของ Astra และ Longzhou เป็นกลุ่ม",
  ui_story_5038_50381002_37_dialog_content = "พวกมันไม่เคยอยู่ในส่วนใดส่วนหนึ่งของมหาสมุทรนานนัก นอกจากช่วงสั้นๆ เมื่ออยู่ใกล้ชายฝั่ง",
  ui_story_5038_50381002_38_dialog_content = "แต่ตอนนี้ดูเหมือนว่ากลุ่มของพวกเขาจะสัญจรไปมาในพื้นที่",
  ui_story_5038_50381002_39_dialog_content = "จริงอยู่ที่วันนี้ลูกเรือจับพวกมันได้เรื่อยๆ",
  ui_story_5038_50381002_40_dialog_content = "พวกเขาจะไม่โจมตีเราอีกแล้วใช่ไหม",
  ui_story_5038_50381002_41_dialog_content = "ดูเหมือนจะไม่เป็นเช่นนั้นในขณะนี้",
  ui_story_5038_50381002_42_dialog_content = "ฉันพยายามอย่างดีที่สุดเพื่อนำทางไปรอบๆ เพื่อหลีกเลี่ยงไม่ให้ซ้ำรอยกับสิ่งที่เกิดขึ้นก่อนหน้านี้",
  ui_story_5038_50381002_43_dialog_content = "แต่พฤติกรรมที่แปลกประหลาดของพวกเขาบ่งบอกถึงสภาวะที่ไม่ปกติในอนาคต",
  ui_story_5038_50381002_44_dialog_content = "บางสิ่งที่นี่ดึงดูดใจปลาช่อนมากกว่าแม้แต่หลงโจว",
  ui_story_5038_50381002_45_dialog_content = "อืมม...",
