  ui_story_5038_50381101_60_dialog_content = "(ทะเลไม่เพียงกลืนกินเรือเท่านั้น แต่รวมถึงลูกเรือและเสียงร้องอันปวดร้าวของพวกเขาด้วย)",
  ui_story_5038_50381101_61_dialog_content = "(มันดูดซับทุกสิ่งที่อยู่ในห้วงลึกลึก ไม่เว้นแม้แต่คลื่น)",
