  ui_story_5038_50381101_63_dialog_content = "(เมื่อทอดสมอที่นี่แล้ว พวกมันจะไม่ออกเรืออีกเลย)",
  ui_story_5038_50381101_64_dialog_content = "(ฉันควรตรวจสอบพวกเขาหรือไม่)",
  ui_story_5038_50381101_65_dialog_content = "(แต่ไม่เห็นเรือลิน...)",
  ui_story_5038_50381101_66_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5038_50381101_67_dialog_content = "เอาล่ะ เรือบดพร้อมสำหรับคุณแล้ว",
  ui_story_5038_50381101_68_dialog_content = "คุณจะไปตอนนี้หรือไม่",
  ui_story_5038_50381101_69_dialog_content = "ใช่ตอนนี้!",
  ui_story_5038_50381101_70_dialog_content = "ให้ฉันไปกับคุณลี่ชิง",
  ui_story_5038_50381101_71_dialog_content = "คุณไปคนเดียวทำให้ฉันเล็กน้อย ...",
  ui_story_5038_50381101_72_dialog_content = "A-คุณไม่กลัวน้ำเหรอ?",
  ui_story_5038_50381101_73_dialog_content = "อืม...",
  ui_story_5038_50381101_74_dialog_content = "ไม่เป็นไร คุณมาด้วยก็ได้",
  ui_story_5038_50381101_75_dialog_content = "ไม้พายยาวเกินไปสำหรับฉันที่จะพายด้วยตัวเอง",
  ui_story_5038_50381101_76_dialog_content = "สมบูรณ์แบบ ไปกันเลย!",
  ui_story_5038_50381101_77_dialog_content = "ย้ายเรือบดไปที่—",
  ui_story_5038_50381101_78_dialog_content = "กรร...",
  ui_story_5038_50381101_79_dialog_content = "...?! เกิดอะไรขึ้นน่ะ?",
  ui_story_5038_50381101_80_dialog_content = "มีบางอย่างเกาะอยู่ในเรือบด!",
  ui_story_5038_50381101_81_dialog_content = "อะไรนะ!",
  ui_story_5038_50381101_82_dialog_content = "ใครจะโง่พอ...",
  ui_story_5038_50381101_83_dialog_content = "ก้าาา!",
  ui_story_5038_50381101_84_dialog_content = "ว้าว ว้าว!",
  ui_story_5038_50381101_85_dialog_content = "ขยะดังกล่าวมาจากไหน!",
  ui_story_5038_50381101_86_dialog_content = "ลงที่นั่น! เชือกผูกเรือบด!",
  ui_story_5038_50381101_87_dialog_content = "Eclipsites กำลังปีนขึ้นไป!",
  ui_story_5038_50381102_1_dialog_content = "กรร...",
  ui_story_5038_50381102_2_dialog_content = "แย่จัง... มือฉันมันสกปรกแล้ว",
  ui_story_5038_50381102_3_dialog_content = "Eclipsites อื่น ๆ ?",
  ui_story_5038_50381102_4_dialog_content = "ไม่ พวกเขาตายหมดแล้ว",
  ui_story_5038_50381102_5_dialog_content = "ดีใจที่ได้ยิน. มาเลย เราต้องไป!",
  ui_story_5038_50381102_6_dialog_content = "คุณแน่ใจหรือว่าต้องการลงไปที่นั่น?",
  ui_story_5038_50381102_7_dialog_content = "มันอาจจะอันตรายกว่าในทะเล",
  ui_story_5038_50381102_8_dialog_content = "กัปตันของคุณเพิ่งดำดิ่งลงไป",
  ui_story_5038_50381102_9_dialog_content = "คุณควรเป็นห่วงเธอมากกว่านี้",
  ui_story_5038_50381102_10_dialog_content = "ไปกันเถอะ PlayerName",
  ui_story_5038_50381102_11_dialog_content = "เอาสิ!",
  ui_story_5038_50381102_12_dialog_content = "อย่าติดตามเรา Tinytail",
  ui_story_5038_50381102_13_dialog_content = "เมี้ยว",
  ui_story_5038_50381102_14_dialog_content = "คุณไม่รู้หรอกว่ามหาสมุทรกว้างใหญ่แค่ไหนจนกว่าคุณจะอยู่ในเรือบด",
  ui_story_5038_50381102_15_dialog_content = "คิดว่าเราจะหาเรือหลินเก่าเจอไหม?",
  ui_story_5038_50381102_16_dialog_content = "เอาล่ะ ผู้นำที่เรามีหมายความว่ามันอยู่ไม่ไกล",
  ui_story_5038_50381102_17_dialog_content = "แต่กลับ...",
  ui_story_5038_50381102_18_dialog_content = "คุณกังวลว่ามันจม?",
  ui_story_5038_50381102_19_dialog_content = "ช่าย",
  ui_story_5038_50381102_20_dialog_content = "แผ่นโลหะลอยอยู่ตามลำพังเหมือนซากปรักหักพังที่เราเคยเห็นมาก่อน",
  ui_story_5038_50381102_21_dialog_content = "บางทีลมก็พัดมา",
  ui_story_5038_50381102_22_dialog_content = "หรือมันถูกฉีกออกโดย Eclipsites ที่ขึ้นเรือ",
  ui_story_5038_50381102_23_dialog_content = "ไม่ว่าจะด้วยวิธีใด สิ่งที่สำคัญคือความจริงที่ว่าเรารู้ว่ามันอยู่ที่ไหนสักแห่งในบริเวณใกล้เคียง",
  ui_story_5038_50381102_24_dialog_content = "เราต้องหาเส้นทางนั้นให้เจอ",
  ui_story_5038_50381102_25_dialog_content = "ฉันชอบที่คุณมั่นใจในเรือลำนั้น",
  ui_story_5038_50381102_26_dialog_content = "แน่นอน. มันถือเข็มทิศ",
  ui_story_5038_50381102_27_dialog_content = "(ฉันรู้สึกว่า Liqing ทุ่มเทให้กับการค้นหา The Compass เป็นพิเศษ)",
  ui_story_5038_50381102_28_dialog_content = "(แต่แรงจูงใจของเขาแตกต่างจากของ Yuebai)",
  ui_story_5038_50381102_29_dialog_content = "(ฉันเข้าใจได้ว่าทำไมเธอถึงรีบร้อน แต่ไม่รู้ว่า Liqing จริงจังกับเรื่องนี้แค่ไหน)",
  ui_story_5038_50381102_30_dialog_content = "(บางทีฉันอาจคุ้นเคยกับวิธีการสบายๆ ของเขามากกว่า)",
  ui_story_5038_50381102_31_dialog_content = "มีอะไรอีก",
  ui_story_5038_50381102_32_dialog_content = "หมอก?",
  ui_story_5038_50381102_33_dialog_content = "ใช่ เรากำลังสูญเสียการมองเห็นอย่างรวดเร็ว",
  ui_story_5038_50381102_34_dialog_content = "นี่มันน่ารำคาญ ลมอยู่ที่ไหนเมื่อคุณต้องการ?",
  ui_story_5038_50381102_35_dialog_content = "เราควรจะหาอะไรในนี้ได้อย่างไร?",
  ui_story_5038_50381102_36_dialog_content = "เอ่อ จู่ ๆ ฉันก็นึกถึงสิ่งที่น่ากังวลยิ่งกว่า...",
  ui_story_5038_50381102_37_dialog_content = "เราจะกลับไปที่ Shadowind ได้อย่างไรถ้าเรามองไม่เห็น?",
  ui_story_5038_50381102_38_dialog_content = "D-จำได้ไหมว่าเรือไปทางไหน?",
  ui_story_5038_50381102_39_dialog_content = "เอ่อ กลับทางนั้นเหรอ?",
  ui_story_5038_50381102_40_dialog_content = "หรืออาจจะไปทางซ้าย?",
  ui_story_5038_50381102_41_dialog_content = "ดังนั้นคุณไม่รู้",
  ui_story_5038_50381102_42_dialog_content = "ถ้าเราตกเรือ...",
  ui_story_5038_50381102_43_dialog_content = "มาเร็ว. มันไม่ได้แย่ขนาดนั้น",
  ui_story_5038_50381102_44_dialog_content = "เรามีคันเบ็ดที่นี่ เราอยู่บนปลาได้ไม่กี่วัน",
  ui_story_5038_50381102_45_dialog_content = "อยากอยู่เกิน \"สองสามวัน\" ขอบคุณมากครับ...",
  ui_story_5038_50381102_46_dialog_content = "แถมถ้าเราไปถึงยานลำเก่ากับ The Compass ก่อน...",
  ui_story_5038_50381102_47_dialog_content = "เราอาจเอาชนะพวกเขาถึงหลงโจวด้วยซ้ำ",
  ui_story_5038_50381102_48_dialog_content = "เราจะเริ่มค้นหาบางสิ่งท่ามกลางหมอกหนาทึบได้อย่างไร?",
  ui_story_5038_50381102_49_dialog_content = "เราควรอยู่เฉย ๆ รอให้หมอกจางหายไปไม่ใช่หรือ?",
  ui_story_5038_50381102_50_dialog_content = "ที่พูดมาก็มีเหตุผล",
  ui_story_5038_50381102_51_dialog_content = "<color=#e8d9bb>สาด!</color>",
  ui_story_5038_50381102_52_dialog_content = "อ๊าาาากกกกกก!!",
  ui_story_5038_50381102_53_dialog_content = "ว่าไง",
  ui_story_5038_50381102_54_dialog_content = "เปียกหมดแล้ว!!!!!!!",
  ui_story_5038_50381102_55_dialog_content = "ไปข้างหลังฉัน Liqing—",
  ui_story_5038_50381102_56_dialog_content = "หยุดตะโกน มีแค่ฉัน",
  ui_story_5038_50381102_57_dialog_content = "ยูไป๋?",
  ui_story_5038_50381102_58_dialog_content = "คุณออกมาจากมหาสมุทร?",
  ui_story_5038_50381102_59_dialog_content = "คุณเห็นอะไรอีกไหมที่นี่?",
  ui_story_5038_50381102_60_dialog_content = "D-คุณต้องลงเอยแบบนี้เหรอ?",
  ui_story_5038_50381102_61_dialog_content = "เอ่อ ฉันเปียกอย่างน่าขยะแขยง...",
  ui_story_5038_50381102_62_dialog_content = "ขอโทษนะ ฉันไม่เคยชินกับความต้องการของโรคกลัวน้ำ",
  ui_story_5038_50381102_63_dialog_content = "อะไรเนี่ย พวกเธอ...",
  ui_story_5038_50381102_64_dialog_content = "ขอจริงจังสักครู่",
  ui_story_5038_50381102_65_dialog_content = "ฉันเพิ่งค้นพบสุสานเรือที่นั่น",
  ui_story_5038_50381102_66_dialog_content = "มีเรือจมจริงๆ...",
  ui_story_5038_50381102_67_dialog_content = "เดี๋ยวก่อน คุณดำลงไปจนสุดก้นมหาสมุทรเลยเหรอ?",
  ui_story_5038_50381102_68_dialog_content = "ฉันจะไม่ทำอย่างนั้นถ้าฉันไม่ใช่นักว่ายน้ำที่เก่งกาจ",
  ui_story_5038_50381102_69_dialog_content = "เมื่อพูดถึงสุสานก็เต็มไปด้วยเรือค้าขาย",
  ui_story_5038_50381102_70_dialog_content = "ฉันมองไปรอบ ๆ แต่ไม่พบเรือหลิน",
  ui_story_5038_50381102_71_dialog_content = "มันเลยไม่มี...",
  ui_story_5038_50381102_72_dialog_content = "คุณสังเกตเห็นอะไรบนพื้นผิวหรือไม่?",
  ui_story_5038_50381102_73_dialog_content = "ไม่นี่",
  ui_story_5038_50381102_74_dialog_content = "กลางคืนมองไม่ค่อยเห็น และตอนนี้หมอกก็บดบังไปหมด",
  ui_story_5038_50381102_75_dialog_content = "ลืมยาน Lin ซะ เราไม่รู้ด้วยซ้ำว่า Shadowind ของเราอยู่ที่ไหนในตอนนี้",
  ui_story_5038_50381102_76_dialog_content = "ฉันคาดหวังมาก",
  ui_story_5038_50381102_77_dialog_content = "เราคงจะไม่พบอะไรในหมอกนี้",
  ui_story_5038_50381102_78_dialog_content = "กลับกันเถอะ ส่งไม้พายให้ฉัน",
  ui_story_5038_50381102_79_dialog_content = "แน่นอน! คุณรู้ไหมว่า Shadowind อยู่ที่ไหน",
  ui_story_5038_50381102_80_dialog_content = "แน่นอน. กัปตันจะทำเรือหายได้อย่างไร?",
  ui_story_5038_50381102_81_dialog_content = "มหัศจรรย์! นั่นทำให้ฉันรู้สึกดีขึ้นมาก!",
  ui_story_5038_50381102_82_dialog_content = "R-Row เร็วกว่านี้ ฉันต้องทำให้ตัวเองแห้งด้วยเตาเผาให้เร็วที่สุด",
  ui_story_5038_50381102_83_dialog_content = "ใช่ ฉันจะไม่ยุ่ง",
  ui_story_5038_50381102_84_dialog_content = "(แถว Yuebai ดีกว่า Liqing หรือฉันมาก)",
  ui_story_5038_50381102_85_dialog_content = "(ด้วยหมอกที่หนาทึบล้อมรอบเรา ฉันไม่สามารถบอกได้ว่าเรือกำลังเคลื่อนที่จริง ๆ นับประสาว่าเราจะไปทางไหน)",
  ui_story_5038_50381102_86_dialog_content = "(Yuebai สามารถหาทางของเธอในหมอกได้หรือไม่?)",
  ui_story_5038_50381102_87_dialog_content = "(แต่ฉันเชื่อใจเธอ เธอพบเรือบดแล้วใช่ไหม เรือใหญ่อย่าง Shadowind ไม่น่าจะมีปัญหา)",
  ui_story_5038_50381102_88_dialog_content = "ฮัดเช่ย!",
  ui_story_5038_50381102_89_dialog_content = "เมื่อผมกลับมา ผมต้องทำตัวให้-",
  ui_story_5038_50381102_90_dialog_content = "เฮ้ย นั่นมัน...?",
  ui_story_5038_50381102_91_dialog_content = "ใช่ เราถึงบ้านแล้ว!",
  ui_story_5038_50381102_92_dialog_content = "ใช่เราเป็น ฉันไม่สามารถบอกได้จนกว่าเราจะใกล้ชิดกัน",
  ui_story_5038_50381102_93_dialog_content = "และนี่เป็นครั้งแรกที่ฉันได้เห็น Shadowind จากมุมนี้",
  ui_story_5038_50381102_94_dialog_content = "ยิ่งใหญ่อลังการมาก...",
  ui_story_5038_50381102_95_dialog_content = "หาคนมาดึงเราขึ้น",
  ui_story_5038_50381102_96_dialog_content = "เฮ้ลูกเรือ!",
  ui_story_5038_50381102_97_dialog_content = "ลงที่นี่!",
  ui_story_5038_50381102_98_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50381102_99_dialog_content = "ไม่มีคำตอบ... พวกเขาทั้งหมดอยู่บนเตียงหรือไม่?",
  ui_story_5038_50381102_100_dialog_content = "ใช่ ทำไมเงียบจัง",
  ui_story_5038_50381102_101_dialog_content = "เฮ้ มีใครได้ยินฉันไหม",
  ui_story_5038_50381102_102_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50381102_103_dialog_content = "แปลกจัง ฉันดังกว่านี้ไม่ได้แล้ว",
  ui_story_5038_50381102_104_dialog_content = "ฉันรู้ว่ามันยากที่จะเห็นในสายหมอก แต่ก็ไม่ยากที่จะได้ยินใช่ไหม?",
  ui_story_5038_50381102_105_dialog_content = "เรือลำนี้...",
  ui_story_5038_50381102_106_dialog_content = "คุณคิดว่าเกิดอะไรขึ้น Yuebai?",
  ui_story_5038_50381102_107_dialog_content = "ลองขึ้นเครื่องและดู",
  ui_story_5038_50381102_108_dialog_content = "ฉันเห็นเชือกตรงนั้น เราสามารถดึงตัวเองขึ้นมาได้",
  ui_story_5038_50381201_1_dialog_content = "หมอกทั้งหมดนี้มาจากไหน?",
  ui_story_5038_50381201_2_dialog_content = "คุณบอกฉัน. กัปตัน Liqing และ PlayerName ยังคงอยู่ที่นั่น ถ้าพวกเขาหายไป...",
  ui_story_5038_50381201_3_dialog_content = "ใครจะรู้ว่าเราจะได้เจอพวกเขาอีกไหม?",
  ui_story_5038_50381201_4_dialog_content = "พวกเขาอยู่ที่นั่น? เพื่ออะไร?",
  ui_story_5038_50381201_5_dialog_content = "พวกเขาพบผู้นำทางไปยัง Shadowind ดั้งเดิมและไปตามหามันบนเรือบด",
  ui_story_5038_50381201_6_dialog_content = "ไม่มีใครคาดคิดว่าหมอกหนาจะลงมาหาเรา",
  ui_story_5038_50381201_7_dialog_content = "บอกทุกคนให้จุดคบเพลิงและคอยเฝ้าหัวเรือ",
  ui_story_5038_50381201_8_dialog_content = "ฉันพับใบเรือแล้วเพื่อลดไม่ให้เรือเคลื่อนที่",
  ui_story_5038_50381201_9_dialog_content = "กัปตันมีทิศทางที่ดี และควรจะหาทางกลับมาได้",
  ui_story_5038_50381201_10_dialog_content = "แต่อีกสองคนก็...",
  ui_story_5038_50381201_11_dialog_content = "คุณ Swindler ทำไมคุณถึงเรียก Jiu กับฉันมาที่นี่?",
  ui_story_5038_50381201_12_dialog_content = "เรามีคนหายไปสามคนและฉันต้องการช่วยตามหาพวกเขา",
  ui_story_5038_50381201_13_dialog_content = "คุณจะไม่สามารถสร้างความแตกต่างได้เนื่องจากหมอกหนาทึบ",
  ui_story_5038_50381201_14_dialog_content = "จะดีกว่าสำหรับคุณที่จะเข้าร่วมกับฉันในห้องโดยสารสำหรับการสนับสนุนทางอารมณ์",
  ui_story_5038_50381201_15_dialog_content = "การสนับสนุนทางอารมณ์? คุณกำลังทำอะไรอยู่?",
