  ui_story_5038_50381202_47_dialog_content = "บางคนในหมู่พวกเขาไม่สามารถแลกคืนได้อย่างแท้จริง บางคนก็แค่พยายามหาเลี้ยงชีพ ผู้คนกลายเป็นอาชญากรด้วยเหตุผลหลายประการ",
