  ui_story_5038_50381401_76_dialog_content = "สิ่งเดียวที่จะเกิดขึ้นที่นี่คือสมบัติของหลิน",
  ui_story_5038_50381401_77_dialog_content = "ชื่อของคุณ.",
  ui_story_5038_50381401_78_dialog_content = "จง... ซู",
  ui_story_5038_50381401_79_dialog_content = "คุณนั่นแหละ",
  ui_story_5038_50381401_80_dialog_content = "สมบัติล้ำค่าที่สุดที่ลินส์มอบให้",
  ui_story_5038_50381401_81_dialog_content = "คุณโย.",
  ui_story_5038_50381401_82_dialog_content = "ลูกใครหว่า? และทำไมเขาถึงทำร้ายลอร์ดจง?",
  ui_story_5038_50381401_83_dialog_content = "ระวังเขามีพลังมาก",
  ui_story_5038_50381401_84_dialog_content = "เด็กน้อยเช่นนี้ได้อย่างไร...",
  ui_story_5038_50381401_85_dialog_content = "เขาอาจจะเป็นจอมวายร้าย?",
  ui_story_5038_50381401_86_dialog_content = "ไม่อยากจะเชื่อเลยว่าตอนนี้คุณหน้าตาแบบนี้...",
  ui_story_5038_50381401_87_dialog_content = "ทำไมคุณถึงโจมตีฉัน",
  ui_story_5038_50381401_88_dialog_content = "ลินส์...สมควร...ที่จะ...ตาย",
  ui_story_5038_50381401_89_dialog_content = "... อย่างที่ฉันสงสัย คุณดูถูกพวกเขา",
  ui_story_5038_50381401_90_dialog_content = "เพราะพวกเขาทำให้คุณเป็นนักโทษ",
  ui_story_5038_50381401_91_dialog_content = "ทุกคน...บน...เรือ...",
  ui_story_5038_50381401_92_dialog_content = "ต้อง...ตาย",
  ui_story_5038_50381401_93_dialog_content = "ฉันพร้อมกับตระกูลหลินคาดเดาความเกลียดชังที่หลีกเลี่ยงไม่ได้ของคุณมานานแล้ว",
  ui_story_5038_50381401_94_dialog_content = "แต่พวกเราไม่มีใครคาดคิดว่าจะต้องเผชิญกับความเกลียดชังนั้นในวันหนึ่ง",
  ui_story_5038_50381401_95_dialog_content = "เรือ...สมควร...ตาย...ที่สุด",
  ui_story_5038_50381401_96_dialog_content = "ความเกลียดชังของคุณได้รับการพิสูจน์แล้ว ดังนั้นคุณยินดีรับมัน",
  ui_story_5038_50381401_97_dialog_content = "เราสืบทอดมรดกของบรรพบุรุษของเราตลอดจนหนี้สินของพวกเขา",
  ui_story_5038_50381401_98_dialog_content = "บางคนโชคร้ายกว่าคนอื่นและติดอยู่ระหว่างสองคนนี้",
  ui_story_5038_50381401_99_dialog_content = "นี่ดูเหมือนจะเป็นความยุ่งเหยิงอีกครั้งที่ฉันต้องประกันตัวคุณ หลิน เพื่อนเก่า",
  ui_story_5038_50381401_100_dialog_content = "ทั้งหมด...ของ...คุณ...คือ...",
  ui_story_5038_50381401_101_dialog_content = "ศัตรู...แห่ง...ท้องทะเล",
  ui_story_5038_50381401_102_dialog_content = "คุณ... และ... เรือลำนี้",
  ui_story_5038_50381401_103_dialog_content = "จม...ลงสู่...มหาสมุทร",
  ui_story_5038_50381401_104_dialog_content = "เกิดอะไรขึ้น?!",
  ui_story_5038_50381401_105_dialog_content = "เดี๋ยวก่อน โย่ว!",
  ui_story_5038_50381401_106_dialog_content = "T-นั่นคือเสียงของ Liqing!",
  ui_story_5038_50381401_107_dialog_content = "ฮึบ... ในที่สุดก็ตามทัน!",
  ui_story_5038_50381401_108_dialog_content = "ลี่...ชิง...",
  ui_story_5038_50381401_109_dialog_content = "นี่คือลักษณะของเข็มทิศ",
  ui_story_5038_50381401_110_dialog_content = "ทำไมทุกคนถึงอยู่ที่นี่? เกิดอะไรขึ้น",
  ui_story_5038_50381401_111_dialog_content = "คุณสามคนอยู่ที่นี่มาตลอดเหรอ?",
  ui_story_5038_50381401_112_dialog_content = "เกิดอะไรขึ้น? แล้วลูกใครล่ะ?",
  ui_story_5038_50381401_113_dialog_content = "นั่นคือเข็มทิศที่เราค้นหา",
  ui_story_5038_50381401_114_dialog_content = "เข็มทิศ?!",
  ui_story_5038_50381401_115_dialog_content = "นักทำนายของฉันไม่มีใครเลือกที่จะเปิดเผยเรื่องนี้กับฉัน ...",
  ui_story_5038_50381401_116_dialog_content = "รอสักครู่การอ่าน!",
  ui_story_5038_50381401_117_dialog_content = "ฉันได้พบกับกลุ่มสัตว์สามตัวที่แปลกประหลาดมาก: หนูที่ลังเล ลิงโง่เขลา และกระต่ายเจ้าเล่ห์",
  ui_story_5038_50381401_118_dialog_content = "\"สิ่งที่เป็นมายากลายเป็นจริง เมื่อความจริงกลายเป็นมายา\" โดยพื้นฐานแล้วมันกำลังบอกเราว่า <color=#FFB400>แทนที่</color> ที่เราเสียไป",
  ui_story_5038_50381401_119_dialog_content = "นั่นคือความหมาย!",
  ui_story_5038_50381401_120_dialog_content = "คุณกำลังเดินเตร่เกี่ยวกับอะไร?",
  ui_story_5038_50381401_121_dialog_content = "ไม้เท้าทำนายการเดินทางทั้งหมด",
  ui_story_5038_50381401_122_dialog_content = "\"หนูที่ลังเล\" เป็นกัปตันที่ลังเลใจระหว่างการค้นหาเข็มทิศและการเดินทางไปยังหลงโจว",
  ui_story_5038_50381401_123_dialog_content = "\"กระต่ายเจ้าเล่ห์\"...คุณคงเคยได้ยินคำพูดที่ว่า \"กระต่ายเจ้าเล่ห์มีที่ซ่อนสามแห่ง\" มันกำลังพูดถึงเข็มทิศ เราไม่รู้ว่ามันคืออะไร ทำอะไร หรืออยู่ที่ไหน",
  ui_story_5038_50381401_124_dialog_content = "ไม้เท้าอันที่สอง \"ลิงโง่\" นำไม้อันแรกและอันสุดท้ายมากระทบกัน",
  ui_story_5038_50381401_125_dialog_content = "มีเพียงการเป็นคนโง่เขลา เดินบนเส้นทางที่เป็นไปไม่ได้ และทำในสิ่งที่เป็นไปไม่ได้เท่านั้น การเดินทางของเราจึงจบลงได้",
  ui_story_5038_50381401_126_dialog_content = "เมื่อคุณบวกไตรแกรมทั้งสามเข้าด้วยกัน คุณจะเห็นว่าสิ่งที่เราตั้งใจจะเปลี่ยนนั้นไม่ใช่ชิ้นส่วนของเรือ",
  ui_story_5038_50381401_127_dialog_content = "มันกำลังพูดถึงเรือทั้งลำ!",
  ui_story_5038_50381401_128_dialog_content = "คุณพยายามทำอะไร Yoh?",
  ui_story_5038_50381401_129_dialog_content = "คุณกำลังพยายามที่จะฆ่าเขา?",
  ui_story_5038_50381401_130_dialog_content = "...",
  ui_story_5038_50381401_131_dialog_content = "ไม่ใช่แค่ฉัน เขาต้องการที่จะจม Shadowind ด้วย",
  ui_story_5038_50381401_132_dialog_content = "ทำไมคุณจะทำเช่นนั้น?",
  ui_story_5038_50381401_133_dialog_content = "ฉันรู้ว่ามันยากแค่ไหนสำหรับคุณที่หมกตัวอยู่ในแท็งก์น้ำขนาดเล็ก",
  ui_story_5038_50381401_134_dialog_content = "และฉันรู้ว่าคุณมีความแค้น คุณรู้สึกโกรธและอาฆาตแค้น",
  ui_story_5038_50381401_135_dialog_content = "แต่ไม่ใช่ว่าทุกคนจะเหมือนกัน ไม่ใช่ทุกคนที่พยายามจะทำร้ายคุณ",
  ui_story_5038_50381401_136_dialog_content = "คุณไม่ควรให้ผู้บริสุทธิ์ชดใช้บาปของผู้อื่น!",
