  ui_story_5038_50381401_146_dialog_content = "คุณ-คุณ—!",
  ui_story_5038_50381401_X146_dialog_content = "เขาเลยจุดที่จะฟังใครอีกต่อไป ถ้าเราไม่หยุดเขา ทุกคนบนเรือจะต้องพินาศ",
