  ui_story_5038_50381402_51_dialog_content = "บรรพบุรุษของ Lin เป็นแรงบันดาลใจให้เกิดความเกลียดชัง ซึ่งฝังรากลึกกับผู้โดยสารทุกคนที่เคยขึ้นเครื่อง",
