  ui_story_5038_50381402_53_dialog_content = "ทุกคนเชื่อว่าหากไม่มีความเกลียดชัง ก็ไม่มีอาชญากรรม และไม่มีอาชญากรรม ก็ไม่จำเป็นต้องรู้สึกผิด",
