  ui_story_5038_50381402_176_dialog_content = "โยนลังนี้ลงน้ำ!",
  ui_story_5038_50381402_177_dialog_content = "ใช่!",
  ui_story_5038_50381402_178_dialog_content = "ว้าว รู้สึกโล่งใจที่ได้โยนสิ่งของลงน้ำ!",
  ui_story_5038_50381402_179_dialog_content = "และนี่ก็เช่นกัน! โยนมัน!",
  ui_story_5038_50381402_180_dialog_content = "เรากำลังทิ้งผ้าห่มทั้งหมด?",
  ui_story_5038_50381402_181_dialog_content = "ใช่ เราจะไม่ได้นอนกันสักพัก",
  ui_story_5038_50381402_182_dialog_content = "เอาล่ะ นี่มันออกทะเลด้วย!",
  ui_story_5038_50381402_183_dialog_content = "สูญเสียทุกสิ่งที่ไม่จำเป็น ทุกบิตมีค่า!",
  ui_story_5038_50381402_184_dialog_content = "เรากำลังต่อสู้กับทะเลไปอีกนาน!",
  ui_story_5038_50381402_185_dialog_content = "จริงอยู่ว่า",
  ui_story_5038_50381402_186_dialog_content = "โยนทิ้งให้หมด!",
  ui_story_5038_50381402_187_dialog_content = "และโต๊ะเก้าอี้และเฟอร์นิเจอร์ทั้งหมด!",
  ui_story_5038_50381402_188_dialog_content = "(คนบนเรือไม่เคยยุ่งกว่านี้อีกแล้ว)",
  ui_story_5038_50381402_189_dialog_content = "(ลูกเรือทุกคนและทุกส่วนของเรือกำลังทำงานอย่างเต็มที่)",
  ui_story_5038_50381402_190_dialog_content = "(มีสองผลลัพธ์ที่เป็นไปได้สำหรับเรา: Sink หรือ Longzhou)",
  ui_story_5038_50381402_191_dialog_content = "(เป็นการต่อสู้ระหว่างสิ่งที่เป็นจริงกับสิ่งที่เป็นอุดมคติ)",
  ui_story_5038_50381402_192_dialog_content = "(ไกลออกไป ในทิศทางที่แผ่นดินอยู่ ดวงอาทิตย์ขึ้นเหนือขอบฟ้า ขณะที่เรือของเรากำลังจมลงเรื่อยๆ)",
  ui_story_5038_50381402_193_dialog_content = "(จักรวาลกำลังรออย่างใจจดใจจ่อที่จะเปิดเผยชะตากรรมสุดท้ายของเรา)",
  ui_story_5038_50381402_194_dialog_content = "เสร็จแล้ว ของถูกท่วมเต็มตู้!",
  ui_story_5038_50381402_195_dialog_content = "มีความคิดอย่างไร ทหารเรือรุ่นเก๋า?",
  ui_story_5038_50381402_196_dialog_content = "ท่วมหมดเลย...",
  ui_story_5038_50381402_197_dialog_content = "ไม่มีอะไรที่เราสามารถทำได้ หากการถือครองถูกน้ำท่วมแล้วต่อไป ...",
  ui_story_5038_50381402_198_dialog_content = "ว้าว มีน้ำอยู่บนดาดฟ้า!",
  ui_story_5038_50381402_199_dialog_content = "เราควรจะทำอะไรตอนนี้...",
  ui_story_5038_50381402_200_dialog_content = "เรากำลังจม...",
  ui_story_5038_50381402_201_dialog_content = "เราทำอะไร เราทำอะไร...",
  ui_story_5038_50381402_202_dialog_content = "กัปตัน! กัปตัน!",
  ui_story_5038_50381402_203_dialog_content = "คุณไปไหนมา? คุณเห็นไหมว่าเกิดอะไรขึ้น—",
  ui_story_5038_50381402_204_dialog_content = "อย่าตื่นตกใจ. แค่รอบนดาดฟ้า",
  ui_story_5038_50381402_205_dialog_content = "Shadowind จะไม่จม",
  ui_story_5038_50381402_206_dialog_content = "<color=#e8d9bb>ปัง! ปัง! ปัง!</color>",
  ui_story_5038_50381402_207_dialog_content = "ว-นั่นอะไรน่ะ?",
  ui_story_5038_50381402_208_dialog_content = "มีบางอย่างกระแทกใต้ท้องเรือ...",
  ui_story_5038_50381402_209_dialog_content = "รอสักครู่! พวกคุณรู้สึกไหม? เราดูเหมือนจะเพิ่มขึ้น!",
  ui_story_5038_50381402_210_dialog_content = "คุณถูก! เกิดอะไรขึ้น—",
  ui_story_5038_50381402_211_dialog_content = "<color=#e8d9bb>ฟิ้วววว!</color>",
  ui_story_5038_50381402_212_dialog_content = "เรากำลังบิน?!",
  ui_story_5038_50381402_213_dialog_content = "L-มองลงไปนั่นสิ! มันปลาช่อนเยอะมาก!",
  ui_story_5038_50381402_214_dialog_content = "พวกเขาแบกเรือไว้บนหลัง!",
  ui_story_5038_50381402_215_dialog_content = "โอ้ช่างน่าทึ่งจริงๆ!",
  ui_story_5038_50381402_216_dialog_content = "ฉันบอกคุณว่าปลางูเหมาะกับทะเลมากกว่าเรือ",
  ui_story_5038_50381402_217_dialog_content = "ใช่ Yoh กำลังช่วยเราอยู่!",
  ui_story_5038_50381402_218_dialog_content = "อยู่มั้ยโย?",
  ui_story_5038_50381402_219_dialog_content = "ขอขอบคุณ!!!",
  ui_story_5038_50381402_220_dialog_content = "คุณคิดไหมว่าสิ่งนี้จะเกิดขึ้นเมื่อคุณปล่อย Yoh ไป Yuebai?",
  ui_story_5038_50381402_221_dialog_content = "ไม่ ไม่มีใครสามารถคาดเดาทิศทางของทะเลชั่วคราวได้",
  ui_story_5038_50381402_222_dialog_content = "ทั้งหมดที่ฉันรู้คือเราทำดีที่สุดแล้ว และบรรลุเป้าหมายทั้งหมดแล้ว",
  ui_story_5038_50381402_223_dialog_content = "ถึงหลงโจวแน่นอน",
  ui_story_5038_50381501_1_dialog_content = "ท่านจงมาหรือยัง",
  ui_story_5038_50381501_2_dialog_content = "รีบพาเขามาที่นี่",
  ui_story_5038_50381501_3_dialog_content = "กำลังมา กำลังมา! ให้ตายเถอะ พวกนายก็แค่สั่งคนไปทั่ว",
  ui_story_5038_50381501_4_dialog_content = "คุณกำลังทำอะไรลี่ชิง?",
  ui_story_5038_50381501_5_dialog_content = "เราไม่อยากให้คุณพลาดวิวสวยๆ",
  ui_story_5038_50381501_6_dialog_content = "ดูนั่นสิ คุณเห็นอะไร?",
  ui_story_5038_50381501_7_dialog_content = "นั่นมัน...?",
  ui_story_5038_50381501_8_dialog_content = "เราถึงบ้านแล้วเหรอ?",
  ui_story_5038_50381501_9_dialog_content = "ใช่ เราถึงบ้านแล้ว! นั่นคือหลงโจว!",
  ui_story_5038_50381501_10_dialog_content = "คุณคิดถึงมันไหม?",
  ui_story_5038_50381501_11_dialog_content = "หลงโจว...",
  ui_story_5038_50381501_12_dialog_content = "ตลอดชีวิตของฉัน ดินที่อยู่ใต้เท้าของฉันแทบไม่มีหลงโจวเลย",
  ui_story_5038_50381501_13_dialog_content = "ฉันไม่ได้คาดหวังว่าตัวเองจะรู้สึกคิดถึงมากขนาดนี้เมื่อได้ยินคุณพูดถึงเรื่องนี้",
  ui_story_5038_50381501_14_dialog_content = "เราหายไปนานเกินไปแล้ว",
  ui_story_5038_50381501_15_dialog_content = "ใช่. เราผ่านอะไรมามากมายและเดินทางมาไกล",
  ui_story_5038_50381501_16_dialog_content = "ในการเดินทางครั้งนี้ เราได้เปลี่ยนเรือ ตอนนี้ฉันก็ต้องนั่งรถเข็นเหมือนกัน",
  ui_story_5038_50381501_17_dialog_content = "มันไม่ง่ายเลยที่ฉันจะทักทายจักรพรรดิในครั้งต่อไปที่ฉันไปเยี่ยมเขา",
  ui_story_5038_50381501_18_dialog_content = "อย่าบอกฉันว่าพระราชวังคือทั้งหมดที่คุณคิดถึงหลงโจว",
  ui_story_5038_50381501_19_dialog_content = "คุณจะรู้สึกคิดถึงเมื่อถึงวัยแบบฉันด้วย",
  ui_story_5038_50381501_20_dialog_content = "ไม่ว่าจะเป็นราชสำนักหรือที่อื่น ๆ ข้าพเจ้าปรารถนาทุกแห่งที่ข้าพเจ้าเคยไป",
  ui_story_5038_50381501_21_dialog_content = "คุยกับคุณมันน่าเบื่อ...",
  ui_story_5038_50381501_22_dialog_content = "แค่บอกฉันว่าตอนนี้คุณเพลิดเพลินกับวิวจากดาดฟ้าหรือไม่?",
  ui_story_5038_50381501_23_dialog_content = "ใช่ ฉันสนุกกับมันมาก",
  ui_story_5038_50381501_24_dialog_content = "ดูสิ งูกำลังว่ายน้ำหนี!",
  ui_story_5038_50381501_25_dialog_content = "แน่นอน. พวกเขาไม่สามารถขึ้นฝั่งกับเราได้",
  ui_story_5038_50381501_26_dialog_content = "พวกเขาจะออกไปทำหน้าที่ของตัวเองหลังจากช่วยเรา",
  ui_story_5038_50381501_27_dialog_content = "หลังจากที่พวกเขาอุ้มท้องมานาน ก็เป็นการบอกลาที่น่าเศร้าเล็กน้อย",
  ui_story_5038_50381501_28_dialog_content = "พวกเขาคงทำให้ฉันเสีย",
  ui_story_5038_50381501_29_dialog_content = "อาจารย์ของฉันบอกว่าการจากลานั้นหวานอมขมกลืนเสมอ",
  ui_story_5038_50381501_30_dialog_content = "แต่เนื่องจากพวกเขาไม่ได้ถูกกำหนดให้อยู่กับเรา จะเป็นการดีที่สุดที่จะจัดการอำลาอย่างเหมาะสม",
  ui_story_5038_50381501_31_dialog_content = "ใช่ฉันคิดว่า การเดินทางทั้งหมดสิ้นสุดลง",
  ui_story_5038_50381501_32_dialog_content = "ลาก่อน! ขอบคุณทุกคน!",
  ui_story_5038_50381501_33_dialog_content = "*สะอื้น* ในที่สุดเราก็ถึงบ้านแล้ว...",
  ui_story_5038_50381501_34_dialog_content = "ใช่ ฉันคิดว่าเราทุกคนจะต้องตายในทะเล",
  ui_story_5038_50381501_35_dialog_content = "มันเยี่ยมมากที่ได้เห็นที่ดิน",
  ui_story_5038_50381501_36_dialog_content = "ทั้งหมดนี้ต้องขอบคุณกัปตัน ถ้าไม่มีเธอ เรือคงจมเป็นสิบรอบ",
  ui_story_5038_50381501_37_dialog_content = "ใช่ เรามีกัปตันที่ยอดเยี่ยม!",
  ui_story_5038_50381501_38_dialog_content = "แค่คิดว่าเธอพาเราไปทำอะไรให้สำเร็จ?",
  ui_story_5038_50381501_39_dialog_content = "เราได้คืนเส้นทาง Lin!",
  ui_story_5038_50381501_40_dialog_content = "เฮ้กัปตันมาแล้ว!",
  ui_story_5038_50381501_41_dialog_content = "นี่กัปตัน! เราแค่ชื่นชมคุณ!",
  ui_story_5038_50381501_42_dialog_content = "ทุกคน...",
  ui_story_5038_50381501_43_dialog_content = "คุณกำลังทำอะไรอยู่ที่นี่? กลับไปที่โพสต์ของคุณ!",
  ui_story_5038_50381501_44_dialog_content = "เรือกำลังเข้าเทียบท่า มันยังไม่จบ.",
  ui_story_5038_50381501_45_dialog_content = "ฟังนะ ยังไม่จบ จนกว่าจะจบ คำสั่งกัปตัน!",
  ui_story_5038_50381501_46_dialog_content = "ค่ะ ค่ะ!",
  ui_story_5038_50381501_47_dialog_content = "ฉัน เอ่อ ประหม่านิดหน่อย",
  ui_story_5038_50381501_48_dialog_content = "ฉันควรทำอย่างไรหลังจากลงจากเรือ",
  ui_story_5038_50381501_49_dialog_content = "คุณประหม่าเรื่องอะไร เพียงติดตามเรา!",
  ui_story_5038_50381501_50_dialog_content = "คุณเพิ่งฝ่าฟันพายุในทะเล การอยู่บนบกจะน่ากลัวกว่าได้อย่างไร?",
  ui_story_5038_50381501_51_dialog_content = "แต่สภาพแวดล้อมเหล่านี้ใหม่ทั้งหมด ...",
  ui_story_5038_50381501_52_dialog_content = "ไม่มีอะไรที่ฉันคุ้นเคย และฉันอยู่คนเดียว",
  ui_story_5038_50381501_53_dialog_content = "คุณหมายความว่าอย่างไรคุณอยู่คนเดียว? ไม่มีเราเหรอ?",
  ui_story_5038_50381501_54_dialog_content = "นั่นสินะ",
  ui_story_5038_50381501_55_dialog_content = "แค่อยู่กับฉันที่หลงโจว แล้วฉันจะทำให้คุณมีเวลาทั้งชีวิต",
  ui_story_5038_50381501_56_dialog_content = "เอาล่ะ เรามาเริ่มเก็บของกันเลย",
  ui_story_5038_50381501_57_dialog_content = "กัปตันขอให้ทุกคนเตรียมพร้อมที่จะลงจากเรือ",
  ui_story_5038_50381501_58_dialog_content = "Hawthorns หวาน!",
  ui_story_5038_50381501_59_dialog_content = "Hawthorns หวานขาย!",
  ui_story_5038_50381501_60_dialog_content = "พวกเขาไปได้เท่าไหร่ครับ?",
  ui_story_5038_50381501_61_dialog_content = "เฮ้ มีร้านทำขนมอยู่ตรงนั้น ไปดูกันเลย!",
  ui_story_5038_50381501_62_dialog_content = "ฉันได้กลิ่นเกี๊ยวหวานนั่นไหม?",
  ui_story_5038_50381501_63_dialog_content = "ว้าว ถนนคึกคัก!",
  ui_story_5038_50381501_64_dialog_content = "คนเยอะ!",
  ui_story_5038_50381501_65_dialog_content = "แล้วเธอว่าไงล่ะ",
  ui_story_5038_50381501_66_dialog_content = "ฉันไม่แน่ใจ... ถนนในหลงโจวมีคนพลุกพล่านตลอดเวลาไหม?",
  ui_story_5038_50381501_67_dialog_content = "ไม่เสมอ. คุณมาทันช่วงท้ายของเทศกาลฤดูใบไม้ผลิพอดี",
  ui_story_5038_50381501_68_dialog_content = "เป็นช่วงเวลาที่ได้รับความนิยมมากที่สุดในหลงโจว ถนนเต็มไปด้วยความสนุกสนานและของอร่อย",
  ui_story_5038_50381501_69_dialog_content = "ดูสิ เด็กคนนั้นถือสิ่งที่เรียกว่า Candied Hawthorn เปรี้ยวหวานและอร่อยมาก",
  ui_story_5038_50381501_70_dialog_content = "และบนโต๊ะนั้นมีรูปปั้นเล็กๆ ที่ทำจากน้ำตาล พวกมันมีไว้ดูเท่านั้นไม่สามารถกินได้",
  ui_story_5038_50381501_71_dialog_content = "แล้วต้มในหม้อใบใหญ่นั้น มีขนมเปี๊ยะ ที่มีเฉพาะช่วงนี้เท่านั้น",
  ui_story_5038_50381501_72_dialog_content = "ว้าว ทุกอย่างดูดี!",
  ui_story_5038_50381501_73_dialog_content = "แค่ถามฉันว่าคุณสงสัยอะไร!",
  ui_story_5038_50381501_74_dialog_content = "ให้ฉันใช้ทั้งหมดนี้ใน",
  ui_story_5038_50381501_75_dialog_content = "แผงขายของที่พื้นโดยที่แม่ค้าเขย่ากระป๋องไม้...",
  ui_story_5038_50381501_76_dialog_content = "อย่าตกหลุมรักสิ่งนั้น! เป็นการหลอกลวงทั้งหมด!",
  ui_story_5038_50381501_77_dialog_content = "หลอกลวง?",
  ui_story_5038_50381501_78_dialog_content = "ใช่ มันเรียกว่าหมอดู ไม่ใช่เรื่องที่ควรค่าแก่การเขียนถึงบ้าน",
  ui_story_5038_50381501_79_dialog_content = "คนปลิ้นปล้อนเหล่านั้นจะพูดอะไรก็ได้เพื่อจับคุณให้ตกเป็นเหยื่อ และคนบาป",
  ui_story_5038_50381501_80_dialog_content = "มันไม่มีอะไรมากไปกว่าการหาเงินเพื่อหลอกเอาเงินของคุณ",
  ui_story_5038_50381501_81_dialog_content = "ทำไมไม่จับเข้าคุก",
  ui_story_5038_50381501_82_dialog_content = "มันค่อนข้างซับซ้อน ...",
  ui_story_5038_50381501_83_dialog_content = "อย่างไรก็ตาม อย่าไปฟังพวกเขา อย่าไว้ใจพวกเขา ถ้าอยากรู้ว่าอนาคตจะเป็นอย่างไร I'm the man!",
  ui_story_5038_50381501_84_dialog_content = "ย-คุณ?",
  ui_story_5038_50381501_85_dialog_content = "ฉันคิดว่าการทำนายเป็นการหลอกลวง?",
  ui_story_5038_50381501_86_dialog_content = "อยู่ที่ว่าใครเป็นผู้ทำนาย ฉันบอกคุณแล้วว่ามันซับซ้อน",
  ui_story_5038_50381501_87_dialog_content = "เฮ้ มีคำพูดในหลงโจวที่ว่า \"การค้าสองฝ่ายไม่ค่อยลงรอยกัน\"",
  ui_story_5038_50381501_88_dialog_content = "ฉันจะให้คุณครุ่นคิดในเรื่องนั้น PlayerName.",
  ui_story_5038_50381501_89_dialog_content = "เคลียร์ทาง เคลียร์ทาง!",
  ui_story_5038_50381501_90_dialog_content = "คุณไม่เห็นรถเข็นผ่านมา?",
  ui_story_5038_50381501_91_dialog_content = "ช้าลงหน่อย Liqing เราจะไม่รบกวนคนอื่น",
  ui_story_5038_50381501_92_dialog_content = "ไม่มีทาง! หลังจากปัญหาทั้งหมดนั้นกลับบ้าน ฉันจะเดินอย่างไรก็ได้ที่ฉันต้องการ!",
  ui_story_5038_50381501_93_dialog_content = "แต่เราจะไปไหนกันหมด กัปตัน?",
  ui_story_5038_50381501_94_dialog_content = "Shadowind เป็นเรือของ Lins แน่นอนฉันต้องกลับไปที่กิลด์ Lin",
  ui_story_5038_50381501_95_dialog_content = "ถ้าไม่รังเกียจ ขอเชิญเข้าพักในฐานะแขกของฉัน",
  ui_story_5038_50381501_96_dialog_content = "สนุกสนานยิ่งขึ้นสำหรับช่วงเทศกาล",
  ui_story_5038_50381501_97_dialog_content = "เรากำลังจะไปใช่ไหม ชายชรา?",
  ui_story_5038_50381501_98_dialog_content = "ฉันหิวแล้ว",
  ui_story_5038_50381501_99_dialog_content = "แน่นอนเราเป็น ฉันจะไปแม้ไม่ได้รับเชิญ",
  ui_story_5038_50381501_100_dialog_content = "Lin Guildmaster เป็นหนี้ฉันค่อนข้างมาก",
  ui_story_5038_50381501_101_dialog_content = "ไม่มีใครเก็บหนี้ในช่วงเทศกาลฤดูใบไม้ผลิ ท่านจง",
  ui_story_5038_50381501_102_dialog_content = "และด้วยสภาพที่กิลด์เป็นอยู่ในขณะนี้ เราคงไม่สามารถจ่ายเงินให้กับนายพลที่เหมาะสมเช่นคุณ นายท่าน",
  ui_story_5038_50381501_103_dialog_content = "นั่นคือความคิด",
  ui_story_5038_50381501_104_dialog_content = "ฉันต้องการให้เขาละอายใจกับข้อเท็จจริงนั้นไปตลอดชีวิต",
  ui_story_5038_50381501_105_dialog_content = "พวกเขากลับมาแล้ว! นักเดินทาง Shadowind กลับมาแล้ว!",
  ui_story_5038_50381501_106_dialog_content = "กรุณาเข้ามา! ต้องเป็นการเดินทางที่ยากลำบาก!",
  ui_story_5038_50381501_107_dialog_content = "คุณต้องเหนื่อย!",
  ui_story_5038_50381501_108_dialog_content = "นี่คือคฤหาสน์หลินเหรอ?",
  ui_story_5038_50381501_109_dialog_content = "ฉันไม่ได้คาดหวังว่าสิ่งก่อสร้างจะค่อนข้างธรรมดาสำหรับกลุ่มที่สร้างเรือขนาดใหญ่เท่า Shadowind",
  ui_story_5038_50381501_110_dialog_content = "ท้ายที่สุดพวกเขาไม่ได้ทำได้ดีมาก",
  ui_story_5038_50381501_111_dialog_content = "ฉันได้ยินมาว่าประตูหน้าของพวกเขาเคยยิ่งใหญ่กว่านี้มาก",
  ui_story_5038_50381501_112_dialog_content = "ฉันไม่ชอบประตูบานใหญ่ มันไม่มีตัวตน",
  ui_story_5038_50381501_113_dialog_content = "มีเทศกาลฤดูใบไม้ผลิที่รู้สึกเหมือนตอนนี้!",
  ui_story_5038_50381501_114_dialog_content = "ทำไมคุณไม่เข้ามาในบ้านตั้งแต่คุณอยู่บ้าน",
  ui_story_5038_50381501_115_dialog_content = "อย่ายืนเฉยๆ",
