  ui_story_5038_50381501_118_dialog_content = "ฉันจะไม่ได้ยินข่าวการกลับมาของ Shadowind ได้อย่างไร?",
  ui_story_5038_50381501_119_dialog_content = "พวกคุณทุกคนเป็นแขกผู้มีเกียรติสำหรับสิ่งที่คุณทำ ฉันน่าจะไปรอคุณที่ท่าเรือด้วยตัวเอง",
