  ui_story_5038_50381501_125_dialog_content = "ทั้งหมดที่ฉันต้องทนทุกข์ทรมานในการต่อสู้เพื่อกองทัพจักรวรรดิตลอดหลายปีที่ผ่านมามีเพียงรอยแผลเป็นเล็กน้อย",
