  ui_story_5038_50381501_193_dialog_content = "ไปที่ Shadowind? ตอนนี้?",
  ui_story_5038_50381501_194_dialog_content = "ใช่ Yuebai รวบรวมทุกคนเข้าด้วยกัน คุณเป็นคนสุดท้าย",
