  ui_story_5038_50381501_208_dialog_content = "ฉันนำจดหมายติดตัวไปที่หลงโจว",
  ui_story_5038_50381501_209_dialog_content = "ฉันใช้เวลาสองวันที่ผ่านมาในการพยายามหาที่อยู่ของผู้รับ แต่ไม่พบ",
