  ui_story_5038_50381501_X222_dialog_content = "<size=35>พรและโชคร้ายมีอยู่ควบคู่กัน แน่นอน การรอดชีวิตที่มีความสุขของเราไม่ได้ปรากฏให้เห็นในอากาศที่เบาบาง</size>",
